import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Sphere, Line } from '@react-three/drei';
import * as THREE from 'three';

export function FamilyTree3D() {
  const dotsRef = useRef<THREE.Group>(null);

  useFrame((state) => {
    if (!dotsRef.current) return;
    const t = state.clock.elapsedTime;
    
    // Pulse gently
    const scale = 1 + Math.sin(t * 3) * 0.2;
    dotsRef.current.children.forEach((child) => {
      child.scale.set(scale, scale, scale);
    });
  });

  const nodes = [
    [0, 0, 0], // root
    [-0.3, 0.4, 0], // left child
    [0.3, 0.4, 0], // right child
    [-0.5, 0.8, 0], // left-left
    [-0.1, 0.8, 0], // left-right
    [0.5, 0.8, 0], // right-right
  ];

  return (
    <group position={[0, -2, 0]}>
      {/* Emerald glow light */}
      <pointLight color="#22C55E" intensity={2} distance={3} />
      
      {/* Connections (Lines) */}
      <Line points={[nodes[0], nodes[1]] as any} color="#22C55E" opacity={0.5} transparent lineWidth={2} />
      <Line points={[nodes[0], nodes[2]] as any} color="#22C55E" opacity={0.5} transparent lineWidth={2} />
      <Line points={[nodes[1], nodes[3]] as any} color="#22C55E" opacity={0.5} transparent lineWidth={2} />
      <Line points={[nodes[1], nodes[4]] as any} color="#22C55E" opacity={0.5} transparent lineWidth={2} />
      <Line points={[nodes[2], nodes[5]] as any} color="#22C55E" opacity={0.5} transparent lineWidth={2} />

      {/* Nodes (Dots) */}
      <group ref={dotsRef}>
        {nodes.map((pos, i) => (
          <Sphere key={i} args={[0.04, 16, 16]} position={pos as [number, number, number]}>
            <meshBasicMaterial color="#ffffff" />
          </Sphere>
        ))}
      </group>
    </group>
  );
}

import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Cone, Cylinder, Box, Octahedron, Sphere } from '@react-three/drei';
import * as THREE from 'three';

export function KeyModel() {
  const humanRef = useRef<THREE.Group>(null);
  const keyRef = useRef<THREE.Group>(null);

  useFrame((state) => {
    const t = state.clock.elapsedTime;
    
    // Slow rotation of the key
    if (keyRef.current) {
      keyRef.current.rotation.y = t * 0.2; // 2rpmish
    }
    
    // Human pulse (solid to translucent)
    if (humanRef.current) {
      const opacity = Math.abs(Math.sin(t)); // 0 to 1 loop (approx 2s)
      humanRef.current.children.forEach((child: any) => {
        if (child.material) {
          child.material.opacity = 0.4 + (opacity * 0.6); // 40% to 100%
        }
      });
    }
  });

  return (
    <group ref={keyRef}>
      {/* Key Bow (Upward Arrow Shape) in Silver */}
      <group position={[0, 2.5, 0]}>
        {/* Arrow point */}
        <Cone args={[0.8, 1, 4]} position={[0, 0.5, 0]} rotation={[0, Math.PI / 4, 0]}>
          <meshPhysicalMaterial color="#E0E0E0" metalness={1} roughness={0.05} clearcoat={1} clearcoatRoughness={0.1} />
        </Cone>
        {/* Arrow base (cutout around human) */}
        <Box args={[1.13, 1, 0.4]} position={[0, -0.5, 0]}>
          <meshPhysicalMaterial color="#C0C0C0" metalness={0.9} roughness={0.15} transmission={0.9} thickness={0.5} ior={1.5} transparent opacity={0.8} />
        </Box>
        
        {/* Human Silhouette inside the bow */}
        <group ref={humanRef} position={[0, -0.5, 0]}>
          <Sphere args={[0.15]} position={[0, 0.3, 0]}>
             <meshStandardMaterial color="#ffffff" emissive="#ffffff" emissiveIntensity={3} transparent />
          </Sphere>
          <Cylinder args={[0.15, 0.2, 0.4]} position={[0, -0.1, 0]}>
             <meshStandardMaterial color="#ffffff" emissive="#ffffff" emissiveIntensity={3} transparent />
          </Cylinder>
        </group>
      </group>

      {/* Key Shaft in Gold */}
      <Cylinder args={[0.15, 0.15, 3]} position={[0, 0.5, 0]}>
        <meshPhysicalMaterial color="#D4AF37" metalness={1} roughness={0.1} clearcoat={0.5} />
      </Cylinder>

      {/* Two Silver 3D hands in V-Shape Cupped Gesture */}
      <group position={[0, 1, 0]}>
         {/* Left Hand approximation */}
         <Box args={[0.8, 0.2, 0.4]} position={[-0.4, -0.4, 0]} rotation={[0, 0, Math.PI / 6]}>
            <meshPhysicalMaterial color="#C0C0C0" metalness={1} roughness={0.2} />
         </Box>
         {/* Right Hand approximation */}
         <Box args={[0.8, 0.2, 0.4]} position={[0.4, -0.4, 0]} rotation={[0, 0, -Math.PI / 6]}>
            <meshPhysicalMaterial color="#C0C0C0" metalness={1} roughness={0.2} />
         </Box>
      </group>

      {/* Key Base (Shield shape / Diamond) */}
      <Octahedron args={[0.8, 0]} position={[0, -1.5, 0]}>
        <meshStandardMaterial color="#111111" metalness={0.7} roughness={0.4} />
      </Octahedron>
    </group>
  );
}

import { useEffect, useState } from 'react';
import { motion, useMotionValue, useSpring } from 'framer-motion';

export default function CustomCursor() {
  const [isHovering, setIsHovering] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  const cursorX = useMotionValue(-100);
  const cursorY = useMotionValue(-100);
  const ringX = useSpring(cursorX, { damping: 22, stiffness: 260, mass: 0.4 });
  const ringY = useSpring(cursorY, { damping: 22, stiffness: 260, mass: 0.4 });

  useEffect(() => {
    // Only show custom cursor on real pointer devices (not touch)
    const canUsePointer = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    if (!canUsePointer) {
      setIsMobile(true);
      return;
    }

    setIsMobile(false);
    document.body.classList.add('custom-cursor-active');

    const onMove = (e: MouseEvent) => {
      cursorX.set(e.clientX);
      cursorY.set(e.clientY);
      if (!isVisible) setIsVisible(true);
    };

    const onOver = (e: MouseEvent) => {
      const t = e.target as HTMLElement;
      setIsHovering(!!t.closest('button, a, input, select, textarea, [role="button"], [tabindex]'));
    };

    const onLeave = () => setIsVisible(false);
    const onEnter = () => setIsVisible(true);

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseover', onOver);
    document.addEventListener('mouseleave', onLeave);
    document.addEventListener('mouseenter', onEnter);

    return () => {
      document.body.classList.remove('custom-cursor-active');
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseover', onOver);
      document.removeEventListener('mouseleave', onLeave);
      document.removeEventListener('mouseenter', onEnter);
    };
  }, [cursorX, cursorY]);

  if (isMobile) return null;

  return (
    <>
      {/* Dot */}
      <motion.div
        className="fixed top-0 left-0 pointer-events-none z-[9999] rounded-full"
        style={{
          width: 7,
          height: 7,
          x: cursorX,
          y: cursorY,
          marginLeft: -3.5,
          marginTop: -3.5,
          backgroundColor: isHovering ? '#10b981' : '#111114',
          opacity: isVisible ? 1 : 0,
        }}
        animate={{ scale: isHovering ? 1.4 : 1 }}
        transition={{ type: 'spring', stiffness: 400, damping: 20 }}
      />
      {/* Ring */}
      <motion.div
        className="fixed top-0 left-0 pointer-events-none z-[9998] rounded-full"
        style={{
          width: 28,
          height: 28,
          x: ringX,
          y: ringY,
          marginLeft: -14,
          marginTop: -14,
          border: isHovering ? '1.5px solid rgba(16,185,129,0.7)' : '1.5px solid rgba(17,17,20,0.25)',
          opacity: isVisible ? 1 : 0,
        }}
        animate={{ scale: isHovering ? 1.6 : 1 }}
        transition={{ type: 'spring', stiffness: 200, damping: 22 }}
      />
    </>
  );
}

import React from 'react';
export class ErrorBoundary extends React.Component<{children: React.ReactNode}, {hasError: boolean, error: any}> {
  constructor(props: any) { super(props); this.state = { hasError: false, error: null }; }
  static getDerivedStateFromError(error: any) { return { hasError: true, error }; }
  componentDidCatch(error: any) { console.error(error); }
  render() { if (this.state.hasError) { return <div style={{padding:'50px',background:'red',color:'white',zIndex:9999,position:'absolute',inset:0}}><h1>Error</h1><pre>{this.state.error?.toString()}</pre><pre>{this.state.error?.stack}</pre></div>; } return this.props.children; }
}

import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { Capsule, MeshTransmissionMaterial } from '@react-three/drei';
import * as THREE from 'three';

interface FloatingCapsuleProps {
  position: [number, number, number];
  color: string;
  speed: number;
  offset: number;
}

function SingleCapsule({ position, color, speed, offset }: FloatingCapsuleProps) {
  const meshRef = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (meshRef.current) {
      const t = state.clock.elapsedTime * speed + offset;
      meshRef.current.position.y = position[1] + Math.sin(t) * 1.5;
      meshRef.current.rotation.x = Math.sin(t * 0.5) * 0.5;
      meshRef.current.rotation.y += 0.01;
      meshRef.current.rotation.z = Math.cos(t * 0.3) * 0.2;
    }
  });

  return (
    <Capsule ref={meshRef} args={[0.4, 0.8, 4, 16]} position={position}>
      <MeshTransmissionMaterial 
        color={color}
        transmission={0.9}
        thickness={0.5}
        roughness={0.1}
        ior={1.5}
      />
      <pointLight distance={3} intensity={0.5} color={color} />
    </Capsule>
  );
}

export function FloatingCapsules({ capsules }: { capsules: any[] }) {
  // Generate a steady array of visual capsules based on actual data
  // Or just decorative if empty
  const visualItems = capsules.length > 0 ? capsules : [{}, {}, {}];

  return (
    <group>
      <ambientLight intensity={0.5} />
      <directionalLight position={[10, 10, 5]} intensity={1} />
      
      {visualItems.map((c, i) => {
        const isLocked = c.isLocked ?? true;
        const color = isLocked ? '#f59e0b' : '#10b981'; // Gold if locked, Green if unlocked
        
        // Distribute them horizontally
        const x = (i % 5) * 2 - 4;
        const z = -Math.random() * 3;
        
        return (
          <SingleCapsule 
            key={c.id || i}
            position={[x, -1, z]}
            color={color}
            speed={0.5 + Math.random() * 0.5}
            offset={Math.random() * Math.PI * 2}
          />
        );
      })}
    </group>
  );
}

import { useStore } from '../../store/useStore';
import { Lock, User, FileText, Key, Mail, ChevronRight } from 'lucide-react';

const icons: Record<string, any> = { Lock, User, FileText, Key, Mail };

export default function ActivityFeed() {
  const { activity } = useStore();

  return (
    <div className="space-y-2">
      {activity.map((item, index) => {
        const Icon = icons[item.icon] || Lock;
        // Mock status based on index for visual variety
        const statusColor = index % 3 === 0 ? 'text-brand-primary bg-brand-primary/10 border-brand-primary/20' 
                          : index % 3 === 1 ? 'text-brand-gold bg-brand-gold/10 border-brand-gold/20' 
                          : 'text-trust-500 bg-trust-500/10 border-trust-500/20';

        return (
          <div 
            key={item.id} 
            className="group flex items-center justify-between p-4 rounded-2xl bg-surface/30 border border-base/50 hover:bg-surface hover:border-base transition-all cursor-default"
          >
            <div className="flex items-center gap-4">
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 border ${statusColor} transition-colors group-hover:scale-105`}>
                <Icon size={16} strokeWidth={2} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-primary truncate group-hover:text-vault-50 transition-colors tracking-tight">
                  {item.message}
                </p>
                <div className="flex items-center gap-2 mt-1">
                  <span className="text-[10px] text-muted font-bold uppercase tracking-widest">{item.time}</span>
                  <span className="w-1 h-1 rounded-full bg-base" />
                  <span className="text-[10px] text-secondary font-mono tracking-tighter">ID: {item.id.slice(0, 8)}</span>
                </div>
              </div>
            </div>
            
            <button className="opacity-0 group-hover:opacity-100 p-2 rounded-full hover:bg-page transition-all">
              <ChevronRight size={16} className="text-muted" />
            </button>
          </div>
        );
      })}
      
      {activity.length === 0 && (
         <div className="py-8 text-center text-[10px] text-muted font-bold uppercase tracking-widest border border-dashed border-base rounded-2xl">
           No recent activity logs.
         </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ShieldCheck, ExternalLink, Shield, RefreshCw } from 'lucide-react';
import { useNotarizationStore } from '../../store/useNotarizationStore';
import Button from '../ui/Button';
import { toast } from 'react-hot-toast';

export default function VaultNotarizationCard() {
  const { notarizeVault, getLatestHash } = useNotarizationStore();
  const [isNotarizing, setIsNotarizing] = useState(false);
  const latestHash = getLatestHash();

  const handleNotarize = async () => {
    setIsNotarizing(true);
    // Simulate API delay
    await new Promise(r => setTimeout(r, 2000));
    await notarizeVault("manual_notarization", { timestamp: Date.now() });
    setIsNotarizing(false);
    toast.success("Vault successfully notarized on blockchain!");
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="p-8 relative overflow-hidden group hover:border-brand-primary/40 transition-all duration-500 bg-surface/30 border border-base/60 rounded-[32px]"
    >
      {/* Decorative Background Elements */}
      <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-emerald-500/5 rounded-full blur-3xl group-hover:bg-emerald-500/10 transition-colors duration-700 pointer-events-none" />
      
      <div className="flex justify-between items-start mb-6 relative z-10">
        <div>
          <h3 className="text-lg font-display font-bold text-primary flex items-center gap-2">
            Vault Notarized <ShieldCheck className="text-emerald-500" size={20} />
          </h3>
          <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-muted/60 mt-1">Blockchain Anchoring</p>
        </div>
        <Shield size={60} className="absolute -top-4 -right-4 text-emerald-500/5 group-hover:text-emerald-500/10 transition-colors pointer-events-none" />
      </div>

      <div className="min-h-[140px] flex flex-col justify-center">
        {latestHash ? (
          <div className="space-y-4 relative z-10">
            <div className="flex justify-between items-center text-sm border-b border-base/50 pb-3">
              <span className="text-[10px] font-bold text-muted uppercase tracking-widest">Last Notarized</span>
              <span className="text-primary font-bold">{new Date(latestHash.createdAt).toLocaleDateString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm border-b border-base/50 pb-3">
              <span className="text-[10px] font-bold text-muted uppercase tracking-widest">Network</span>
              <span className="text-brand-primary font-bold capitalize">{latestHash.chain}</span>
            </div>
            <div className="flex flex-col gap-2 pt-1">
              <span className="text-[10px] font-bold text-muted uppercase tracking-widest">Transaction Hash</span>
              <div className="bg-page/50 p-3 rounded-xl truncate text-[11px] font-mono text-emerald-400 border border-emerald-500/20 shadow-inner">
                {latestHash.blockchainRef}
              </div>
            </div>
          </div>
        ) : (
          <div className="text-sm text-secondary font-medium mb-6 bg-page/50 p-5 rounded-2xl border border-base shadow-inner text-center">
            Your vault hasn't been notarized yet. Timestamp your instructions on the blockchain to make them legally defensible.
          </div>
        )}
      </div>

      <div className="flex gap-3 relative z-10 mt-6">
        <button 
          className={`flex-1 py-4 rounded-2xl text-[11px] font-bold uppercase tracking-widest flex items-center justify-center gap-2 transition-all shadow-lg ${
            isNotarizing 
              ? 'bg-emerald-500/20 text-emerald-500 border border-emerald-500/30 cursor-wait' 
              : 'bg-emerald-500 text-obsidian-950 hover:bg-emerald-400 hover:scale-[1.02] active:scale-[0.98]'
          }`}
          onClick={handleNotarize}
          disabled={isNotarizing}
        >
          {isNotarizing ? (
            <>
              <RefreshCw size={14} className="animate-spin" />
              Anchoring...
            </>
          ) : 'Notarize Now'}
        </button>
        {latestHash && (
          <button 
            className="w-14 rounded-2xl bg-surface border border-base flex items-center justify-center text-muted hover:text-brand-primary hover:border-brand-primary/30 transition-all"
            title="View on Explorer"
          >
             <ExternalLink size={16} />
          </button>
        )}
      </div>
    </motion.div>
  );
}

import { motion, AnimatePresence } from 'framer-motion';
import { useStore } from '../../store/useStore';
import { X, Key, User, FileText, AlertTriangle, CheckCircle } from 'lucide-react';

const icons: Record<string, any> = {
  Key, User, FileText, AlertTriangle, CheckCircle
};

export default function NotificationDrawer() {
  const { notifications, isNotificationOpen, toggleNotifications, markNotificationAsRead } = useStore();

  return (
    <AnimatePresence>
      {isNotificationOpen && (
        <motion.div
          initial={{ x: '100%' }}
          animate={{ x: 0 }}
          exit={{ x: '100%' }}
          transition={{ type: 'spring', damping: 20 }}
          className="fixed inset-y-0 right-0 w-80 bg-surface/95 backdrop-blur-xl border-l border-border z-[100] shadow-2xl flex flex-col pt-16"
        >
          <div className="p-4 border-b border-border flex justify-between items-center">
            <h2 className="text-lg font-semibold text-text">Notifications</h2>
            <button onClick={toggleNotifications} className="text-muted hover:text-text transition">
              <X size={24} />
            </button>
          </div>
          
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {notifications.length === 0 ? (
              <p className="text-muted text-center pt-8">No notifications</p>
            ) : (
              notifications.map((n) => {
                const Icon = icons[n.icon] || AlertTriangle;
                return (
                  <button 
                    key={n.id} 
                    onClick={() => !n.read && markNotificationAsRead(n.id)}
                    className={`p-4 rounded-xl glassmorphism flex items-start space-x-3 w-full text-left transition-colors ${!n.read ? 'border-primary/50 bg-primary/5 hover:bg-primary/10' : 'hover:bg-surface'}`}
                  >
                    <div className={`p-2 rounded-full ${!n.read ? 'bg-primary/20 text-primary' : 'bg-surface text-muted'}`}>
                      <Icon size={16} />
                    </div>
                    <div className="flex-1">
                      <p className={`text-sm ${!n.read ? 'text-text font-medium' : 'text-muted'}`}>{n.message}</p>
                    </div>
                  </button>
                );
              })
            )}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

import React from 'react';
import { NavLink } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Shield, 
  Users, 
  Package, 
  History, 
  Settings, 
  HelpCircle,
  ChevronLeft,
  ChevronRight,
  LogOut,
  Bell,
  Code2,
  Lock,
  BarChart2
} from 'lucide-react';
import { useStore } from '../../store/useStore';
import { cn } from '../../utils/cn';

const navItems = [
  { icon: LayoutDashboard, label: 'Dashboard', path: '/' },
  { icon: BarChart2, label: 'Analytics', path: '/analytics' },
  { icon: Package, label: 'Asset Vault', path: '/vault' },
  { icon: Users, label: 'Guardians', path: '/guardians' },
  { icon: Shield, label: 'Trust Center', path: '/trust' },
  { icon: Lock, label: 'AI Planner', path: '/planner' },
  { icon: Code2, label: 'Dev Portal', path: '/developer' },
  { icon: History, label: 'Activity', path: '/activity' },
];

const bottomItems = [
  { icon: Settings, label: 'Settings', path: '/settings' },
  { icon: HelpCircle, label: 'Support', path: '/support' },
];

export default function Sidebar() {
  const { isSidebarCollapsed, toggleSidebar, user } = useStore();

  return (
    <aside
      className={cn(
        "fixed left-0 top-16 h-[calc(100vh-4rem)] bg-surface border-r border-base transition-all duration-300 z-40 flex flex-col hidden lg:flex",
        isSidebarCollapsed ? "w-20" : "w-64"
      )}
    >
      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto py-6 px-3 space-y-1 custom-scrollbar">
        {navItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            className={({ isActive }) => cn(
              "flex items-center gap-3 px-4 py-3 rounded-xl transition-all group relative",
              isActive 
                ? "bg-brand-primary/10 text-brand-primary border border-brand-primary/20" 
                : "text-secondary hover:text-primary hover:bg-page hover:text-primary border border-transparent"
            )}
          >
            <item.icon size={20} className={cn(
              "shrink-0 transition-transform group-hover:scale-110",
              "group-[.active]:text-brand-primary"
            )} />
            {!isSidebarCollapsed && (
              <span className="font-medium text-sm tracking-tight">{item.label}</span>
            )}
            {isSidebarCollapsed && (
              <div className="absolute left-full ml-4 px-3 py-2 bg-raised border border-base rounded-lg text-xs font-bold text-primary opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all whitespace-nowpawn pointer-events-none z-[60] shadow-xl">
                {item.label}
              </div>
            )}
          </NavLink>
        ))}
      </nav>

      {/* Bottom Actions */}
      <div className="p-3 border-t border-base space-y-1">
        {bottomItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            className={({ isActive }) => cn(
              "flex items-center gap-3 px-4 py-3 rounded-xl transition-all group relative",
              isActive 
                ? "bg-brand-primary/10 text-brand-primary border border-brand-primary/20" 
                : "text-secondary hover:text-primary hover:bg-page hover:text-primary border border-transparent"
            )}
          >
            <item.icon size={20} />
            {!isSidebarCollapsed && (
              <span className="font-medium text-sm tracking-tight">{item.label}</span>
            )}
          </NavLink>
        ))}

        {/* User Profile / Logout */}
        <div className={cn(
          "mt-4 p-3 rounded-2xl bg-page/50 border border-base flex items-center gap-3",
          isSidebarCollapsed ? "justify-center px-0" : "px-3"
        )}>
          <div className="w-8 h-8 rounded-full bg-raised border border-base flex items-center justify-center shrink-0 overflow-hidden">
            {user.avatar ? (
              <img src={user.avatar} alt={user.name} className="w-full h-full object-cover" />
            ) : (
              <span className="text-[10px] font-bold text-muted">{user.name.charAt(0)}</span>
            )}
          </div>
          {!isSidebarCollapsed && (
            <div className="flex-1 min-w-0">
              <p className="text-xs font-bold text-primary truncate">{user.name}</p>
              <p className="text-[10px] text-muted truncate">{user.email}</p>
            </div>
          )}
          {!isSidebarCollapsed && (
            <button className="text-muted hover:text-error transition-colors">
              <LogOut size={14} />
            </button>
          )}
        </div>
      </div>

      {/* Collapse Toggle */}
      <button
        onClick={toggleSidebar}
        className="absolute -right-3 top-10 w-6 h-6 rounded-full bg-surface border border-base flex items-center justify-center text-muted hover:text-brand-primary hover:border-brand-primary/50 transition-all z-[60] shadow-lg"
      >
        {isSidebarCollapsed ? <ChevronRight size={12} /> : <ChevronLeft size={12} />}
      </button>
    </aside>
  );
}

