                  <h4 className="text-xs font-bold text-primary uppercase tracking-widest mb-1 group-hover:text-green-400 transition-colors">Integrity Verified</h4>
                  <p className="text-[10px] text-muted font-medium leading-relaxed">Your sovereign BTC recovery path has reached a 100% verification threshold with 3 active guardians.</p>
                </div>
              </motion.div>
            </div>
          </div>
        </div>

      </main>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useStore } from '../store/useStore';
import { motion, AnimatePresence } from 'framer-motion';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import Card from '../components/ui/Card';
import Badge from '../components/ui/Badge';
import { PieChart, HeartHandshake, Box, Wallet, Users, Plus, Trash2, ArrowRight, AlertCircle, Briefcase, ShieldCheck, ChevronRight } from 'lucide-react';
import toast from 'react-hot-toast';
import { PieChart as RePieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

const fadeUp = (delay = 0) => ({
  initial: { opacity: 0, y: 15 },
  whileInView: { opacity: 1, y: 0 },
  viewport: { once: true },
  transition: { delay, duration: 0.5, ease: [0.16, 1, 0.3, 1] },
});

export default function Allocations() {
  const { assets, heirs, charities, allocations, addAllocation, updateAllocation, removeAllocation } = useStore();
  const [selectedAssetId, setSelectedAssetId] = useState<string | null>(assets.length > 0 ? assets[0].id : null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalTab, setModalTab] = useState<'heir' | 'charity'>('heir');

  const selectedAsset = assets.find(a => a.id === selectedAssetId);
  const assetAllocations = allocations.filter(a => a.assetId === selectedAssetId);
  const totalAllocated = assetAllocations.reduce((sum, a) => sum + a.percentage, 0);
  const remainingPercent = 100 - totalAllocated;

  const handleSliderChange = (id: string, newValue: number, oldValue: number) => {
    const diff = newValue - oldValue;
    if (diff > remainingPercent) {
      updateAllocation(id, oldValue + remainingPercent);
    } else {
      updateAllocation(id, newValue);
    }
  };

  const addRecipient = (recipientId: string, type: 'heir' | 'charity') => {
    if (assetAllocations.find(a => a.recipientId === recipientId)) {
      toast.error('Protocol conflict: Recipient already assigned.');
      return;
    }
    if (remainingPercent <= 0) {
      toast.error('Resource depletion: Asset is fully allocated.');
      return;
    }
    addAllocation({
      assetId: selectedAssetId!,
      recipientId,
      type,
      percentage: Math.min(25, remainingPercent)
    });
    setIsModalOpen(false);
    toast.success('Recipient synchronized');
  };

  const getRecipientDetails = (a: any) => {
    if (a.type === 'heir') {
      const h = heirs.find(heir => heir.id === a.recipientId);
      return { name: h?.name || 'Unknown Heir', icon: Users, color: '#4F5CFF' }; // brand-primary
    } else {
      const c = charities.find(charity => charity.id === a.recipientId);
      return { name: c?.name || 'Institutional Charity', icon: HeartHandshake, color: '#D4AF37' }; // brand-gold
    }
  };

  const chartData = useMemo(() => {
    const data = assetAllocations.map(a => {
      const details = getRecipientDetails(a);
      return { name: details.name, value: a.percentage, color: details.color };
    });
    if (remainingPercent > 0) {
      data.push({ name: 'Unassigned Protocol', value: remainingPercent, color: 'rgba(255,255,255,0.05)' });
    }
    return data;
  }, [assetAllocations, remainingPercent]);

  return (
    <div className="min-h-screen bg-page text-primary selection:bg-brand-primary/30 pt-20">
      <main className="px-4 sm:px-6 lg:px-8 pb-28 md:pb-12 max-w-7xl mx-auto space-y-10">
        
        {/* ── Page Header ── */}
        <motion.header {...fadeUp(0)} className="flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <span className="w-2 h-2 rounded-full bg-brand-primary" />
              <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-brand-primary">
                Asset Allocation Protocol
              </p>
            </div>
            <h1 className="text-4xl sm:text-5xl font-display font-bold text-primary tracking-tight leading-none">
              Smart <span className="italic text-brand-primary">Allocations</span>
            </h1>
            <p className="text-muted text-sm mt-3 font-medium">
              Precisely route institutional assets to beneficiaries and mandates.
            </p>
          </div>
        </motion.header>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          
          {/* ── Asset Inventory Sidebar ── */}
          <motion.div {...fadeUp(0.1)} className="lg:col-span-3 space-y-4">
            <div className="flex items-center justify-between px-2 mb-2">
              <p className="text-[10px] font-bold uppercase tracking-widest text-primary0">Vault Inventory</p>
              <Badge variant="default" className="text-[9px]">{assets.length} Assets</Badge>
            </div>
            <div className="space-y-3 max-h-[600px] overflow-y-auto pr-2 scrollbar-hide">
              {assets.length === 0 ? (
                <div className="p-10 text-center border border-dashed border-base rounded-2xl bg-surface/20">
                  <p className="text-xs text-obsidian-600 font-bold uppercase tracking-widest leading-relaxed">No assets detected in primary vault.</p>
                </div>
              ) : (
                assets.map(asset => (
                  <button
                    key={asset.id}
                    onClick={() => setSelectedAssetId(asset.id)}
                    className={`w-full text-left p-5 rounded-2xl transition-all duration-300 border flex items-center gap-4 group ${
                      selectedAssetId === asset.id 
                        ? 'bg-brand-primary/10 border-brand-primary/40 shadow-[0_0_20px_rgba(79,92,255,0.1)]' 
                        : 'bg-surface/50 border-base text-primary0 hover:border-base hover:bg-surface'
                    }`}
                  >
                    <div className={`w-12 h-12 rounded-xl flex items-center justify-center transition-all ${selectedAssetId === asset.id ? 'bg-brand-primary text-obsidian-950' : 'bg-surface/80 text-primary0 border border-base'}`}>
                      {asset.type === 'Crypto' ? <Wallet size={18} /> :
                       asset.type === 'Retirement' ? <Briefcase size={18} /> : <Box size={18} />}
                    </div>
                    <div className="flex-1 overflow-hidden">
                      <p className={`font-bold text-sm tracking-tight truncate ${selectedAssetId === asset.id ? 'text-primary' : ''}`}>{asset.name}</p>
                      <p className="text-[10px] font-mono mt-1 opacity-60">${asset.value?.toLocaleString() || 0}</p>
                    </div>
                    {selectedAssetId === asset.id && <ChevronRight size={14} className="text-brand-primary" />}
                  </button>
                ))
              )}
            </div>
          </motion.div>

          {/* ── Distribution Matrix Canvas ── */}
          <motion.div {...fadeUp(0.2)} className="lg:col-span-9">
            <Card variant="default" className="bg-surface/50 border-base min-h-[600px] flex flex-col relative overflow-hidden">
              {!selectedAssetId || !selectedAsset ? (
                <div className="flex-1 flex flex-col items-center justify-center p-12 text-center">
                  <div className="w-20 h-20 rounded-full bg-page border border-base flex items-center justify-center mb-6 opacity-30">
                    <PieChart size={32} />
                  </div>
                  <h3 className="text-xl font-display font-bold text-secondary">Awaiting Asset Selection</h3>
                  <p className="text-sm text-primary0 mt-2 max-w-xs font-medium italic">Select an asset from your vault inventory to configure distribution protocols.</p>
                </div>
              ) : (
                <>
                  <div className="p-8 border-b border-base bg-surface/30 flex flex-col md:flex-row md:items-center justify-between gap-6">
                    <div>
                      <h2 className="text-2xl font-display font-bold text-primary tracking-tight">{selectedAsset.name}</h2>
                      <p className="text-sm text-primary0 mt-1 font-medium">Vault Allocation Value: <strong className="text-brand-primary font-mono tracking-tight">${selectedAsset.value?.toLocaleString() || 0}</strong></p>
                    </div>
                    <div className={`px-5 py-2.5 rounded-2xl border text-[10px] font-bold uppercase tracking-[0.2em] flex items-center gap-3 shadow-inner ${
                      remainingPercent === 0 
                        ? 'bg-brand-primary/10 border-brand-primary/30 text-brand-primary' 
                        : 'bg-brand-gold/10 border-brand-gold/30 text-brand-gold'
                    }`}>
                      {remainingPercent === 0 ? <ShieldCheck size={14} /> : <AlertCircle size={14} />}
                      {remainingPercent === 0 ? 'Full Protocol Sync' : `${remainingPercent}% Buffer Remaining`}
                    </div>
                  </div>

                  <div className="flex-1 p-8 lg:p-12 grid grid-cols-1 xl:grid-cols-2 gap-12 items-start">
                    
                    {/* ── Recipient Sliders ── */}
                    <div className="space-y-8">
                      <div className="flex justify-between items-end">
                        <h3 className="text-xs font-bold uppercase tracking-widest text-primary0">Beneficiary Matrix</h3>
                        <Button variant="secondary" onClick={() => setIsModalOpen(true)} className="h-8 px-4 text-[10px] font-bold uppercase tracking-widest">
                          <Plus size={14} className="mr-2" /> Add Mandate
                        </Button>
                      </div>

                      {assetAllocations.length === 0 ? (
                         <div className="p-12 text-center border border-dashed border-base rounded-3xl bg-page/30">
                           <p className="text-xs text-primary0 font-bold uppercase tracking-widest mb-6 leading-relaxed italic">No beneficiaries assigned to this asset.</p>
                           <Button variant="primary" onClick={() => setIsModalOpen(true)} className="h-11 px-8 font-bold">Initialize Distribution</Button>
                         </div>
                      ) : (
                        <div className="space-y-5">
                          <AnimatePresence>
                            {assetAllocations.map(a => {
                              const details = getRecipientDetails(a);
                              const Icon = details.icon;
                              const valueAmount = (selectedAsset.value || 0) * (a.percentage / 100);
                              
                              return (
                                <motion.div 
                                  key={a.id}
                                  initial={{ opacity: 0, x: 10 }}
                                  animate={{ opacity: 1, x: 0 }}
                                  exit={{ opacity: 0, scale: 0.95 }}
                                  className="p-6 bg-page/50 rounded-2xl border border-base hover:border-brand-primary/30 transition-all group"
                                >
                                  <div className="flex justify-between items-start mb-6">
                                    <div className="flex items-center gap-4">
                                      <div className="w-10 h-10 rounded-xl bg-surface border border-base flex items-center justify-center" style={{ color: details.color }}>
                                        <Icon size={16} />
                                      </div>
                                      <div>
                                        <span className="block font-bold text-sm text-primary tracking-tight">{details.name}</span>
                                        <span className="block text-[9px] uppercase tracking-widest text-obsidian-600 font-bold mt-1">{a.type} ALLOCATION</span>
                                      </div>
                                    </div>
                                    <button onClick={() => removeAllocation(a.id)} className="text-obsidian-700 hover:text-red-500 transition-colors p-2 hover:bg-red-500/5 rounded-lg">
                                      <Trash2 size={16} />
                                    </button>
                                  </div>
                                  
                                  <div className="flex items-center gap-6">
                                    <input 
                                      type="range" 
                                      min="1" 
                                      max="100" 
                                      value={a.percentage}
                                      onChange={(e) => handleSliderChange(a.id, parseInt(e.target.value), a.percentage)}
                                      className="flex-1 h-1.5 bg-surface/80 rounded-full appearance-none cursor-pointer accent-brand-primary" 
                                    />
                                    <span className="w-14 text-right font-mono font-bold text-brand-primary text-lg">{a.percentage}%</span>
                                  </div>
                                  
                                  <div className="mt-4 flex justify-end">
                                    <span className="text-[10px] font-bold text-obsidian-600 uppercase tracking-widest">Est. Value: <span className="text-obsidian-200">${valueAmount.toLocaleString(undefined, { maximumFractionDigits: 0 })}</span></span>
                                  </div>
                                </motion.div>
                              );
                            })}
                          </AnimatePresence>
                        </div>
                      )}
                    </div>

                    {/* ── Visual Allocation Visualization ── */}
                    <div className="flex flex-col items-center justify-center p-10 bg-page/30 rounded-3xl border border-base/50 h-full min-h-[400px]">
                       <div className="w-full h-72 relative">
                         <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-10">
                            <p className="text-[10px] font-bold text-obsidian-600 uppercase tracking-[0.2em] mb-1">Vault Sync</p>
                            <p className="text-2xl font-display font-bold text-primary">{100 - remainingPercent}%</p>
                         </div>
                         <ResponsiveContainer width="100%" height="100%">
                            <RePieChart>
                              <Pie
                                data={chartData}
                                cx="50%"
                                cy="50%"
                                innerRadius={85}
                                outerRadius={120}
                                paddingAngle={8}
                                dataKey="value"
                                stroke="none"
                              >
                                {chartData.map((entry, index) => (
                                  <Cell key={`cell-${index}`} fill={entry.color} />
                                ))}
                              </Pie>
                              <Tooltip 
                                formatter={(value: any) => [`${value}%`, 'Protocol Sync']}
                                contentStyle={{ backgroundColor: 'rgb(10 10 12)', border: '1px solid rgb(39 39 42)', borderRadius: '16px', color: '#f8fafc', fontSize: '12px', fontWeight: 'bold' }}
                                itemStyle={{ color: '#818cf8' }}
                              />
                            </RePieChart>
                         </ResponsiveContainer>
                       </div>
                       
                       {assetAllocations.length > 0 && (
                         <div className="mt-10 grid grid-cols-2 gap-x-8 gap-y-3">
                            {chartData.map((d, i) => (
                              <div key={i} className="flex items-center gap-3">
                                <span className="w-2.5 h-2.5 rounded-full shadow-[0_0_10px_rgba(0,0,0,0.5)]" style={{ backgroundColor: d.color }}></span>
                                <span className="text-[10px] font-bold text-primary0 uppercase tracking-widest truncate max-w-[120px]">{d.name}</span>
                              </div>
                            ))}
                         </div>
                       )}
                    </div>

                  </div>
                </>
              )}
            </Card>
          </motion.div>
        </div>

      </main>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Recipient Authorization">
         <div className="flex p-1 bg-page rounded-2xl border border-base mb-8 shadow-inner">
           <button 
             onClick={() => setModalTab('heir')}
             className={`flex-1 py-3 text-xs font-bold uppercase tracking-widest rounded-xl transition-all duration-300 ${modalTab === 'heir' ? 'bg-brand-primary text-obsidian-950 shadow-lg' : 'text-primary0 hover:text-obsidian-200'}`}
           >
             Heirs
           </button>
           <button 
             onClick={() => setModalTab('charity')}
             className={`flex-1 py-3 text-xs font-bold uppercase tracking-widest rounded-xl transition-all duration-300 flex items-center justify-center gap-2 ${modalTab === 'charity' ? 'bg-brand-gold text-obsidian-950 shadow-lg' : 'text-primary0 hover:text-obsidian-200'}`}
           >
             <HeartHandshake size={14} /> Charities
           </button>
         </div>

         <div className="max-h-[400px] overflow-y-auto space-y-3 pr-2 scrollbar-hide">
           {modalTab === 'heir' ? (
             heirs.length === 0 ? <p className="text-center text-obsidian-600 font-bold uppercase tracking-widest p-12 text-[10px] italic">No registered heirs detected.</p> :
             heirs.map(heir => (
               <button 
                 key={heir.id}
                 onClick={() => addRecipient(heir.id, 'heir')}
                 className="w-full text-left p-5 rounded-2xl border border-base bg-surface/50 hover:border-brand-primary/40 hover:bg-surface transition-all flex justify-between items-center group shadow-sm"
               >
                 <div>
                   <p className="font-bold text-primary tracking-tight group-hover:text-brand-primary transition-colors">{heir.name}</p>
                   <p className="text-[10px] font-mono text-obsidian-600 mt-1 uppercase tracking-widest">{heir.email}</p>
                 </div>
                 <ArrowRight size={18} className="text-obsidian-700 group-hover:text-brand-primary group-hover:translate-x-1 transition-all" />
               </button>
             ))
           ) : (
             charities.map(charity => (
               <button 
                 key={charity.id}
                 onClick={() => addRecipient(charity.id, 'charity')}
                 className="w-full text-left p-5 rounded-2xl border border-base bg-surface/50 hover:border-brand-gold/40 hover:bg-surface transition-all flex justify-between items-center group shadow-sm"
               >
                 <div className="pr-4">
                   <p className="font-bold text-primary tracking-tight group-hover:text-brand-gold transition-colors">{charity.name}</p>
                   <p className="text-[9px] text-brand-gold/60 font-bold uppercase tracking-widest mt-1 mb-2">{charity.category}</p>
                   <p className="text-xs text-primary0 italic line-clamp-1">{charity.description}</p>
                 </div>
                 <Plus size={18} className="text-obsidian-700 group-hover:text-brand-gold transition-all flex-shrink-0" />
               </button>
             ))
           )}
         </div>
      </Modal>
    </div>
  );
}

import { useState } from 'react';
import { useStore } from '../store/useStore';
import { Wallet, Plus, Edit2, Trash2, Box, TrendingUp, Briefcase, FileText, Globe, Search, Shield, ChevronRight, LayoutGrid, List } from 'lucide-react';
import Button from '../components/ui/Button';
import Badge from '../components/ui/Badge';
import Modal from '../components/ui/Modal';
import Input from '../components/ui/Input';
import Select from '../components/ui/Select';
import { useForm as useRHForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import toast from 'react-hot-toast';
import { motion, AnimatePresence } from 'framer-motion';
import { calculateProjection } from '../utils/mathUtils';
import Card from '../components/ui/Card';

const assetSchema = z.object({
  name: z.string().min(1, 'Name is required'),
  type: z.string().min(1, 'Type is required'),
  value: z.number().optional().or(z.nan()),
  notes: z.string().optional()
});

const fadeUp = (delay = 0) => ({
  initial: { opacity: 0, y: 15 },
  whileInView: { opacity: 1, y: 0 },
  viewport: { once: true },
  transition: { delay, duration: 0.5, ease: [0.16, 1, 0.3, 1] },
});

export default function Assets() {
  const { assets, addAsset, updateAsset, deleteAsset } = useStore();
  const [activeTab, setActiveTab] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  
  const tabs = ['All', 'Crypto', 'NFTs', 'Documents', 'Accounts', 'Institutional', 'Other'];
  
  const filteredAssets = activeTab === 'All' 
    ? assets 
    : assets.filter(a => {
        if (activeTab === 'Crypto') return a.type === 'Crypto' || a.type === 'Wallet';
        if (activeTab === 'NFTs') return a.type === 'NFT';
        if (activeTab === 'Documents') return a.type === 'Document' || a.type === 'Legal';
        if (activeTab === 'Accounts') return a.type === 'Account' || a.type === 'Login';
        if (activeTab === 'Institutional') return a.type === 'Retirement' || a.type === 'Bank';
        return a.type === activeTab;
      });

  const totalValue = assets.reduce((acc, a) => acc + (a.value || 0), 0);

  const { register, handleSubmit, reset, formState: { errors } } = useRHForm({
    resolver: zodResolver(assetSchema)
  });

  const onSubmit = (data: any) => {
    if (editingId) {
      updateAsset(editingId, { ...data, date: new Date().toISOString().split('T')[0] });
      toast.success('Vault record updated');
    } else {
      addAsset({
        ...data,
        status: 'Protected',
        date: new Date().toISOString().split('T')[0],
        tags: [data.type.toLowerCase()]
      });
      toast.success('Asset secured in vault');
    }
    setIsModalOpen(false);
    setEditingId(null);
    reset();
  };

  const openAddModal = () => {
    setEditingId(null);
    reset({ name: '', type: '', value: undefined, notes: '' });
    setIsModalOpen(true);
  };

  const openEditModal = (asset: any) => {
    setEditingId(asset.id);
    reset(asset);
    setIsModalOpen(true);
  };

  const handleQuickAddInstitutional = () => {
    addAsset({
      name: 'Capital Trust Retirement',
      type: 'Retirement',
      value: 150000,
      growthRate: 0.07,
      status: 'Protected',
      date: new Date().toISOString().split('T')[0],
      tags: ['retirement', 'institutional', 'long-term'],
      notes: 'Institutional retirement fund. Managed via primary brokerage.'
    } as any);
    toast.success('Institutional template added');
  };

  return (
    <div className="min-h-screen bg-page text-primary selection:bg-brand-primary/30 pt-20">
      <main className="px-4 sm:px-6 lg:px-8 pb-28 md:pb-12 max-w-7xl mx-auto space-y-10">
        
        {/* ── Page Header ── */}
        <motion.header {...fadeUp(0)} className="flex flex-col md:flex-row md:items-end justify-between gap-8">
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-brand-primary shadow-[0_0_10px_rgba(79,92,255,0.8)]" />
              <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-brand-primary">
                Asset Inventory Protocol
              </p>
            </div>
            <h1 className="text-4xl sm:text-5xl lg:text-5xl font-display font-bold text-primary tracking-tight leading-none">
              Asset <span className="italic text-brand-primary">Vault</span>
            </h1>
            <p className="text-muted text-sm font-medium max-w-xl">
              Securely archive your entire digital and institutional portfolio. {assets.length} items currently protected with <span className="text-obsidian-200">${totalValue.toLocaleString()}</span> in institutional value.
            </p>
          </div>
          <div className="flex flex-wrap gap-4">
            <Button onClick={() => handleQuickAddInstitutional()} variant="secondary" className="h-12 px-8 text-[10px] font-bold uppercase tracking-widest border-base">
              <Briefcase size={16} className="mr-2" /> Quick Template
            </Button>
            <Button onClick={openAddModal} variant="primary" className="h-12 px-8 text-[10px] font-bold uppercase tracking-widest shadow-xl shadow-brand-primary/10">
              <Plus size={18} className="mr-2" /> Add New Asset
            </Button>
          </div>
        </motion.header>

        {/* ── Tabs / Search / View Toggle ── */}
        <motion.div {...fadeUp(0.05)} className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 border-b border-base/60 pb-6">
          <div className="flex space-x-1 overflow-x-auto pb-2 lg:pb-0 scrollbar-hide">
            {tabs.map(tab => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-6 py-2.5 rounded-xl whitespace-nowrap text-[10px] font-bold uppercase tracking-widest transition-all ${
                  activeTab === tab 
                  ? 'bg-surface/80 text-brand-primary shadow-xl border border-base' 
                  : 'text-primary0 hover:text-secondary'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>
          <div className="flex items-center gap-4">
            <div className="relative group flex-1 lg:flex-none">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-obsidian-600 group-focus-within:text-brand-primary transition-colors" size={16} />
              <input 
                type="text" 
                placeholder="Search protocol records..."
                className="bg-surface border border-base rounded-2xl pl-11 pr-4 py-3 text-sm text-obsidian-200 focus:border-brand-primary/50 w-full lg:w-72 transition-all placeholder:text-obsidian-700"
              />
            </div>
            <div className="flex bg-surface border border-base rounded-xl p-1">
              <button 
                onClick={() => setViewMode('grid')}
                className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-surface/80 text-brand-primary shadow-sm' : 'text-obsidian-600'}`}
              >
                <LayoutGrid size={18} />
              </button>
              <button 
                onClick={() => setViewMode('list')}
                className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-surface/80 text-brand-primary shadow-sm' : 'text-obsidian-600'}`}
              >
                <List size={18} />
              </button>
            </div>
          </div>
        </motion.div>

        {/* ── Asset Content ── */}
        <AnimatePresence mode="wait">
          {viewMode === 'grid' ? (
            <motion.div 
              key="grid"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
            >
              {filteredAssets.map((asset, i) => (
                <Card
                  key={asset.id}
                  {...fadeUp(0.1 + i * 0.05)}
                  className="p-8 group hover:border-brand-primary/30 transition-all cursor-default bg-surface/40 relative overflow-hidden"
                >
                  <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-transparent via-brand-primary/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                  
                  <div className="flex justify-between items-start mb-8">
                    <div className="flex items-center space-x-5">
                      <div className="w-14 h-14 rounded-2xl bg-page flex items-center justify-center border border-base group-hover:bg-brand-primary/10 group-hover:border-brand-primary/30 transition-all duration-500 shadow-inner">
                        {asset.type === 'Crypto' ? <Wallet size={24} className="text-orange-400" /> :
                         asset.type === 'NFT' ? <Box size={24} className="text-pink-400" /> :
                         asset.type === 'Retirement' ? <Briefcase size={24} className="text-trust-500" /> :
                         asset.type === 'Document' ? <FileText size={24} className="text-brand-primary" /> :
                         <Globe size={24} className="text-brand-primary" />}
                      </div>
                      <div>
                        <h3 className="text-xl font-display font-bold text-primary tracking-tight group-hover:text-vault-50 transition-colors">{asset.name}</h3>
                        <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-primary0 mt-1">{asset.type}</p>
                      </div>
                    </div>
                    <div className="flex flex-col items-end gap-2">
                       <Badge variant={asset.status === 'Protected' ? 'success' : 'warning'} className="text-[9px] font-bold uppercase tracking-widest px-3">
                         {asset.status === 'Protected' ? 'Encrypted' : asset.status}
                       </Badge>
                       <Shield size={14} className="text-brand-primary/40" />
                    </div>
                  </div>
                  
                  {/* Projections */}
                  {((asset as any).growthRate || asset.type === 'Retirement' || asset.type === 'Crypto') && (
                    <div className="mb-8 p-5 bg-page/80 rounded-2xl border border-base/40 group-hover:border-brand-primary/10 transition-colors shadow-inner">
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center gap-2">
                          <TrendingUp size={12} className="text-trust-500" />
                          <span className="text-[9px] font-bold uppercase tracking-[0.2em] text-obsidian-600">Archival Projection</span>
                        </div>
                        <span className="text-[9px] font-bold text-trust-500/60 uppercase">10Y @ 7%</span>
                      </div>
                      <p className="text-2xl font-display font-bold text-trust-500">
                        ${calculateProjection(asset.value || 0, (asset as any).growthRate || 0.07, 10).toLocaleString(undefined, { maximumFractionDigits: 0 })}
                      </p>
                    </div>
                  )}
                  
                  <div className="mt-auto pt-8 border-t border-base/60 flex justify-between items-end">
                    <div>
                      <p className="text-[9px] font-bold text-obsidian-600 uppercase tracking-widest mb-1.5">Current Valuation</p>
                      <p className="text-3xl font-display font-bold text-primary">${asset.value?.toLocaleString() || '0'}</p>
                    </div>
                    <div className="flex space-x-3">
                      <button 
                        onClick={() => openEditModal(asset)} 
                        className="p-3 bg-page hover:bg-surface/80 rounded-xl text-primary0 hover:text-brand-primary transition-all border border-base hover:border-brand-primary/30 shadow-inner"
                      >
                        <Edit2 size={16} />
                      </button>
                      <button 
                        onClick={() => { deleteAsset(asset.id); toast.success('Removed from vault'); }} 
                        className="p-3 bg-page hover:bg-red-500/10 rounded-xl text-obsidian-700 hover:text-red-500 transition-all border border-base hover:border-red-500/30 shadow-inner"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </div>
                </Card>
              ))}
            </motion.div>
          ) : (
            <motion.div 
              key="list"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="bg-surface/40 rounded-[32px] border border-base/60 overflow-hidden"
            >
              <table className="w-full text-left">
                <thead className="bg-page border-b border-base">
                  <tr>
                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-[0.2em] text-primary0">Asset Designation</th>
                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-[0.2em] text-primary0">Type</th>
                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-[0.2em] text-primary0">Valuation</th>
                    <th className="px-8 py-5 text-[10px] font-bold uppercase tracking-[0.2em] text-primary0">Protocol Status</th>
                    <th className="px-8 py-5 text-right"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-obsidian-800/60">
                  {filteredAssets.map((asset) => (
                    <tr key={asset.id} className="hover:bg-surface/80/20 transition-colors group">
                      <td className="px-8 py-6">
                        <div className="flex items-center gap-4">
                          <div className="w-10 h-10 rounded-lg bg-page flex items-center justify-center border border-base group-hover:border-brand-primary/30 transition-colors">
                            {asset.type === 'Crypto' ? <Wallet size={18} className="text-orange-400" /> :
                             asset.type === 'NFT' ? <Box size={18} className="text-pink-400" /> :
                             asset.type === 'Retirement' ? <Briefcase size={18} className="text-trust-500" /> :
                             asset.type === 'Document' ? <FileText size={18} className="text-brand-primary" /> :
                             <Globe size={18} className="text-brand-primary" />}
                          </div>
                          <span className="font-display font-bold text-primary">{asset.name}</span>
                        </div>
                      </td>
                      <td className="px-8 py-6 text-xs text-muted font-bold uppercase tracking-widest">{asset.type}</td>
                      <td className="px-8 py-6 font-display font-bold text-primary">${asset.value?.toLocaleString()}</td>
                      <td className="px-8 py-6">
                        <Badge variant={asset.status === 'Protected' ? 'success' : 'warning'} className="text-[9px] font-bold uppercase tracking-widest px-3">
                          {asset.status === 'Protected' ? 'Encrypted' : asset.status}
                        </Badge>
                      </td>
                      <td className="px-8 py-6 text-right">
                        <button onClick={() => openEditModal(asset)} className="p-2 text-obsidian-600 hover:text-brand-primary transition-colors"><Edit2 size={16}/></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </motion.div>
          )}
        </AnimatePresence>

        {filteredAssets.length === 0 && (
          <motion.div {...fadeUp(0.2)} className="text-center py-32 bg-surface/30 rounded-[40px] border border-dashed border-base/60">
            <div className="w-20 h-20 bg-page rounded-3xl flex items-center justify-center mx-auto mb-6 border border-base shadow-inner">
              <Box size={32} className="text-obsidian-700" />
            </div>
            <h3 className="text-2xl font-display font-bold text-obsidian-200">Vault Empty</h3>
            <p className="text-primary0 text-sm mt-2 max-w-xs mx-auto font-medium">No archived records found in the {activeTab} sector. Initiate your first security protocol.</p>
            <Button onClick={openAddModal} variant="primary" className="mt-8 px-10 py-3 text-[10px] font-bold uppercase tracking-[0.2em]">
              <Plus size={18} className="mr-2" /> Secure Asset
            </Button>
          </motion.div>
        )}
      </main>

      {/* ── Security Input Modal ── */}
      <Modal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setEditingId(null); reset(); }} title={editingId ? "Update Protocol Record" : "New Security Protocol"}>
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-6 pt-4">
          <Select 
            label="Asset Sector"
            {...register('type')}
            error={errors.type?.message as string}
            options={[
              { value: '', label: 'Select Sector' },
              { value: 'Crypto', label: 'Cryptocurrency / Web3' },
              { value: 'NFT', label: 'Digital Collectible' },
              { value: 'Retirement', label: 'Institutional Retirement' },
              { value: 'Document', label: 'Legacy Document' },
              { value: 'Account', label: 'Authorized Login' },
            ]}
          />
          <Input 
            label="Designation"
            placeholder="e.g. Primary Institutional Custody"
            {...register('name')}
            error={errors.name?.message as string}
          />
          <Input 
            label="Market Valuation (USD)"
            type="number"
            {...register('value', { valueAsNumber: true })}
            placeholder="0.00"
          />
          <div className="flex flex-col space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-primary0 ml-1">Succession Protocol Instructions</label>
            <textarea 
              className="w-full bg-page border border-base rounded-2xl px-5 py-4 text-obsidian-100 text-sm focus:border-brand-primary/50 transition-all placeholder:text-obsidian-800 leading-relaxed min-h-[140px]"
              rows={4}
              placeholder="Detail the specific distribution mandates for this asset..."
              {...register('notes')}
            ></textarea>
          </div>
          <Button variant="primary" fullWidth type="submit" className="h-14 mt-6 text-[11px] font-bold uppercase tracking-[0.2em] shadow-xl shadow-brand-primary/20">
            {editingId ? 'Update Record' : 'Initiate Security Protocol'}
          </Button>
        </form>
      </Modal>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Shield, ShieldAlert, CheckCircle, Clock, Bell, History, Settings, Fingerprint, Mail, Activity, ChevronRight, AlertTriangle } from 'lucide-react';
import { useCheckinStore } from '../store/useCheckinStore';
import { Canvas } from '@react-three/fiber';
import { CheckInHeart } from '../components/checkin/CheckInHeart';
import Button from '../components/ui/Button';
import Card from '../components/ui/Card';
import Badge from '../components/ui/Badge';

const fadeUp = (delay = 0) => ({
  initial: { opacity: 0, y: 15 },
  whileInView: { opacity: 1, y: 0 },
  viewport: { once: true },
  transition: { delay, duration: 0.5, ease: [0.16, 1, 0.3, 1] },
});

export default function CheckInCenter() {
  const { checkins, checkinSettings, completeCheckin, updateSettings, simulateMissedCheckin } = useCheckinStore();
  const [showSettings, setShowSettings] = useState(false);
  const [timeRemaining, setTimeRemaining] = useState('');
  const [showConfetti, setShowConfetti] = useState(false);

  const isAlertMode = checkinSettings.status !== 'active';
  const misses = checkinSettings.currentStreak === 0 ? checkinSettings.totalMissed : 0; 

  // Update countdown timer
  useEffect(() => {
    const updateTime = () => {
      const last = checkinSettings.lastCheckinAt ? new Date(checkinSettings.lastCheckinAt) : new Date(Date.now() - 86400000);
      const nextDue = new Date(last);
      if (checkinSettings.frequency === 'weekly') nextDue.setDate(nextDue.getDate() + 7);
      if (checkinSettings.frequency === 'biweekly') nextDue.setDate(nextDue.getDate() + 14);
      if (checkinSettings.frequency === 'monthly') nextDue.setMonth(nextDue.getMonth() + 1);

      const diff = nextDue.getTime() - Date.now();
      if (diff <= 0) {
        setTimeRemaining('Overdue');
      } else {
        const d = Math.floor(diff / (1000 * 60 * 60 * 24));
        const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
        const m = Math.floor((diff / 1000 / 60) % 60);
        setTimeRemaining(`${d}d ${h}h ${m}m`);
      }
    };
    updateTime();
    const interval = setInterval(updateTime, 60000);
    return () => clearInterval(interval);
  }, [checkinSettings]);

  const handleCheckIn = () => {
    completeCheckin('tap');
    setShowConfetti(true);
    setTimeout(() => setShowConfetti(false), 2000);
  };

  return (
    <div className="min-h-screen bg-page text-primary selection:bg-brand-primary/30 pt-20">
      <main className="px-4 sm:px-6 lg:px-8 pb-24 md:pb-12 max-w-5xl mx-auto space-y-12">
        
        {/* ── Page Header ── */}
        <motion.header {...fadeUp(0)} className="flex flex-col md:flex-row md:items-end justify-between gap-6">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <span className={`w-2 h-2 rounded-full ${isAlertMode ? 'bg-red-500 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.8)]' : 'bg-brand-primary shadow-[0_0_10px_rgba(79,92,255,0.8)]'}`} />
              <p className={`text-[10px] font-bold uppercase tracking-[0.2em] ${isAlertMode ? 'text-red-500' : 'text-brand-primary'}`}>
                {isAlertMode ? 'Emergency Alert Status' : 'Vault Heartbeat Protocol'}
              </p>
            </div>
            <h1 className="text-4xl sm:text-5xl font-display font-bold text-primary tracking-tight leading-none">
              Proof of <span className="italic text-brand-primary">Life</span>
            </h1>
            <p className="text-muted text-sm mt-3 font-medium">
              Maintain sovereign control through periodic verification pulses.
            </p>
          </div>
          <div className="flex items-center gap-4">
             <Badge variant={isAlertMode ? 'secondary' : 'default'} className="px-4 py-1.5 text-[10px] uppercase tracking-widest font-bold">
               {isAlertMode ? 'Protocol Violated' : 'Operational Sync'}
             </Badge>
          </div>
        </motion.header>

        {/* ── Heartbeat Visualization ── */}
        <motion.div {...fadeUp(0.1)} className="h-64 w-full rounded-[32px] bg-surface/40 border border-base/60 relative overflow-hidden flex items-center justify-center backdrop-blur-sm group">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(79,92,255,0.05),transparent)] opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
          <Canvas camera={{ position: [0, 0, 5] }}>
            <CheckInHeart isAlert={isAlertMode} />
          </Canvas>
          <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_center,transparent_0%,rgba(10,10,12,0.6)_100%)]" />
          <div className="absolute bottom-6 left-0 right-0 text-center pointer-events-none">
            <p className="text-[9px] font-bold uppercase tracking-[0.4em] text-obsidian-600">Sovereign Pulse Active</p>
          </div>
        </motion.div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
          
          {/* ── Main Status Matrix ── */}
          <motion.div {...fadeUp(0.2)} className="lg:col-span-2 space-y-6">
            <Card variant="default" className="p-8 bg-surface/50 border-base/60 relative">
              <div className="grid grid-cols-2 gap-8 mb-10">
                <div className="p-6 bg-page/50 rounded-2xl border border-base/50 group hover:border-brand-primary/30 transition-all">
                  <p className="text-[10px] font-bold text-primary0 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <History size={12} className="text-brand-primary" /> Last Pulse
                  </p>
                  <p className="text-xl font-display font-bold text-primary tracking-tight">
                    {checkinSettings.lastCheckinAt ? new Date(checkinSettings.lastCheckinAt).toLocaleDateString() : 'Uninitialized'}
                  </p>
                </div>
                <div className="p-6 bg-page/50 rounded-2xl border border-base/50 group hover:border-brand-primary/30 transition-all">
                  <p className="text-[10px] font-bold text-primary0 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <Clock size={12} className="text-brand-primary" /> Next Window
                  </p>
                  <p className={`text-xl font-display font-bold tracking-tight ${timeRemaining === 'Overdue' ? 'text-red-500' : 'text-brand-primary'}`}>
                    {timeRemaining}
                  </p>
                </div>
                <div className="p-6 bg-page/50 rounded-2xl border border-base/50 group hover:border-brand-primary/30 transition-all">
                  <p className="text-[10px] font-bold text-primary0 uppercase tracking-widest mb-3">Violation Misses</p>
                  <p className="text-xl font-display font-bold text-primary tracking-tight flex items-center gap-3">
                    {misses} 
                    {misses > 0 && <span className="w-2.5 h-2.5 rounded-full bg-red-500 shadow-[0_0_10px_rgba(239,68,68,0.5)]"></span>}
                  </p>
                </div>
                <div className="p-6 bg-brand-primary/5 rounded-2xl border border-brand-primary/20 group hover:bg-brand-primary/10 transition-all">
                  <p className="text-[10px] font-bold text-brand-primary/80 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <Activity size={12} /> Sync Streak
                  </p>
                  <p className="text-xl font-display font-bold text-brand-primary tracking-tight">
                    {checkinSettings.currentStreak} <span className="text-sm">Days</span>
                  </p>
                </div>
              </div>

              <div className="relative">
                <AnimatePresence>
                  {showConfetti && (
                    <motion.div 
                      initial={{ scale: 0.5, opacity: 1 }}
                      animate={{ scale: 2, opacity: 0 }}
                      exit={{ opacity: 0 }}
                      className="absolute inset-0 flex items-center justify-center pointer-events-none z-20"
                    >
                      <CheckCircle className="text-brand-primary w-32 h-32 blur-sm" />
                    </motion.div>
                  )}
                </AnimatePresence>
                
                <motion.button
                  whileHover={{ scale: 1.01 }}
                  whileTap={{ scale: 0.99 }}
                  onClick={handleCheckIn}
                  className="w-full py-8 rounded-3xl relative overflow-hidden group bg-brand-primary text-obsidian-950 shadow-2xl shadow-brand-primary/20 transition-all active:scale-95"
                >
                  <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/30 to-white/0 translate-x-[-100%] group-hover:animate-[shimmer_2s_infinite]"></div>
                  <span className="relative z-10 flex items-center justify-center gap-4 text-2xl font-display font-bold uppercase tracking-tighter">
                    <Fingerprint size={32} /> Initialize Verification Pulse
                  </span>
                </motion.button>
              </div>
            </Card>

            {/* ── History Timeline ── */}
            <Card className="p-8 bg-surface/30 border-base/60">
              <h3 className="text-xs font-bold uppercase tracking-widest text-primary0 mb-8 flex items-center gap-3">
                <History size={16} className="text-brand-primary" /> Pulse Verification History
              </h3>
              <div className="space-y-4">
                {checkins.slice(0, 8).map((checkin) => (
                  <div key={checkin.id} className="flex items-center justify-between p-5 rounded-2xl bg-page/50 border border-base/50 hover:border-brand-primary/20 transition-all group">
                    <div className="flex items-center gap-5">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
                        checkin.status === 'responded' ? 'bg-brand-primary/10 text-brand-primary' :
                        checkin.status === 'missed' ? 'bg-red-500/10 text-red-500' : 'bg-amber-500/10 text-amber-500'
                      }`}>
                        {checkin.method === 'tap' ? <Fingerprint size={18}/> : <Mail size={18}/>}
                      </div>
                      <div>
                        <p className="text-sm font-bold text-primary tracking-tight group-hover:text-brand-primary transition-colors capitalize">{checkin.status}</p>
                        <p className="text-[10px] text-obsidian-600 font-bold uppercase tracking-widest mt-1.5">{new Date(checkin.scheduledFor).toLocaleString()}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-6">
                      <span className={`text-[9px] font-bold uppercase tracking-[0.2em] px-3 py-1 rounded-full bg-surface border ${
                         checkin.status === 'responded' ? 'border-brand-primary/20 text-brand-primary' : 'border-red-500/20 text-red-400'
                      }`}>
                        {checkin.method}
                      </span>
                      <ChevronRight size={14} className="text-obsidian-800" />
                    </div>
                  </div>
                ))}
                {checkins.length === 0 && (
                  <p className="text-center text-obsidian-600 font-bold uppercase tracking-widest py-16 text-[10px] italic">No pulse history recorded in vault.</p>
                )}
              </div>
            </Card>
          </motion.div>

          {/* ── Settings & Tools ── */}
          <motion.div {...fadeUp(0.3)} className="space-y-8">
            <Card className="p-8 bg-surface/50 border-base/60">
              <div className="flex justify-between items-center mb-8">
                <h3 className="text-xs font-bold uppercase tracking-widest text-primary0 flex items-center gap-3">
                  <Settings size={16} className="text-brand-primary"/> Protocol Config
                </h3>
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  className="text-[10px] font-bold text-brand-primary uppercase tracking-widest hover:underline"
                >
                  {showSettings ? 'Close' : 'Modify'}
                </button>
              </div>

              {showSettings ? (
                <div className="space-y-8">
                  <div>
                    <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-obsidian-600 mb-4 block">Verification Frequency</label>
                    <div className="grid grid-cols-1 gap-2">
                      {['weekly', 'biweekly', 'monthly'].map(f => (
                        <button 
                          key={f}
                          onClick={() => updateSettings({ frequency: f as any })}
                          className={`px-5 py-3 rounded-xl text-xs font-bold uppercase tracking-widest border transition-all ${
                            checkinSettings.frequency === f 
                              ? 'bg-brand-primary/10 text-brand-primary border-brand-primary/40 shadow-[0_0_15px_rgba(79,92,255,0.1)]' 
                              : 'bg-page text-primary0 border-base hover:border-base'
                          }`}
                        >
                          {f}
                        </button>
                      ))}
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-obsidian-600 block mb-4">
                      Alert Quorum After: {checkinSettings.alertGuardiansAfterMisses} Misses
                    </label>
                    <input 
                      type="range" 
                      min="1" 
                      max="3" 
                      value={checkinSettings.alertGuardiansAfterMisses} 
                      onChange={(e) => updateSettings({ alertGuardiansAfterMisses: parseInt(e.target.value) })}
                      className="w-full h-1.5 bg-surface/80 rounded-full appearance-none cursor-pointer accent-brand-primary"
                    />
                  </div>
                </div>
              ) : (
                <div className="space-y-6">
                   <div className="flex justify-between items-center p-4 rounded-xl bg-page/40 border border-base/60">
                      <span className="text-[10px] font-bold uppercase tracking-widest text-obsidian-600">Interval</span>
                      <span className="text-xs font-bold text-obsidian-200 capitalize">{checkinSettings.frequency}</span>
                   </div>
                   <div className="flex justify-between items-center p-4 rounded-xl bg-page/40 border border-base/60">
                      <span className="text-[10px] font-bold uppercase tracking-widest text-obsidian-600">Quorum Trigger</span>
                      <span className="text-xs font-bold text-obsidian-200">{checkinSettings.alertGuardiansAfterMisses} Misses</span>
                   </div>
                   <div className="flex justify-between items-center p-4 rounded-xl bg-page/40 border border-base/60">
                      <span className="text-[10px] font-bold uppercase tracking-widest text-obsidian-600">Succession Depth</span>
                      <span className="text-xs font-bold text-obsidian-200">{checkinSettings.consecutiveMissesAllowed} Misses</span>
                   </div>
                </div>
              )}
            </Card>

            {/* ── Intelligence Alerts ── */}
            <div className="p-8 rounded-[32px] bg-red-500/5 border border-red-500/20 relative group overflow-hidden">
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                 <AlertTriangle size={80} className="text-red-500" />
              </div>
              <h3 className="text-xs font-bold text-red-500 uppercase tracking-widest mb-4 flex items-center gap-3">
                <Bell size={16}/> Protocol Testing
              </h3>
              <p className="text-[10px] text-muted font-medium leading-relaxed mb-6">Simulation of missed verification pulses triggers guardian alerts and starts the succession countdown.</p>
              <Button 
                variant="secondary" 
                className="w-full py-4 text-[10px] font-bold uppercase tracking-widest text-red-500 border-red-500/30 hover:bg-red-500/10" 
                onClick={() => simulateMissedCheckin()}
              >
                Simulate Violation Pulse
              </Button>
            </div>
          </motion.div>
        </div>

      </main>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Mail, MapPin, Send, MessageSquare, Clock } from 'lucide-react';
import toast from 'react-hot-toast';

interface ContactConfig {
  office_address: string;
  map_embed_url: string;
  emails: { label: string; email: string }[];
  phones: { label: string; number: string }[];
  social_links: Record<string, string>;
  working_hours: { days: string; hours: string }[];
}

export default function ContactUs() {
  const [config, setConfig] = useState<ContactConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: '',
    message: ''
  });

  useEffect(() => {
    async function fetchContact() {
      try {
        const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8080/v1';
        const res = await fetch(`${API_URL}/app/contact`);
        if (res.ok) {
          const data = await res.json();
          setConfig(data);
        }
      } catch (err) {
        console.error('Failed to fetch contact details', err);
      } finally {
        setLoading(false);
      }
    }
    fetchContact();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8080/v1';
      const res = await fetch(`${API_URL}/app/contact/message`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });
      if (res.ok) {
        toast.success('Message sent! We will get back to you soon.');
        setFormData({ name: '', email: '', subject: '', message: '' });
      } else {
        throw new Error('Failed to send message');
      }
    } catch (err) {
      toast.error('Failed to send message. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0B0E14] flex items-center justify-center">
        <motion.div 
          animate={{ rotate: 360 }}
          transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
          className="w-8 h-8 border-2 border-indigo-500 border-t-transparent rounded-full"
        />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0B0E14] text-white selection:bg-indigo-500/30">
      {/* Hero Section */}
      <section className="relative pt-32 pb-20 overflow-hidden">
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full h-full pointer-events-none">
          <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500/10 blur-[120px] rounded-full" />
          <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/10 blur-[120px] rounded-full" />
        </div>

        <div className="max-w-7xl mx-auto px-6 relative z-10">
          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center max-w-3xl mx-auto"
          >
            <h1 className="text-5xl md:text-5xl font-bold mb-6 bg-gradient-to-r from-white via-white to-white/50 bg-clip-text text-transparent">
              Let's Start a Conversation
            </h1>
            <p className="text-xl text-slate-400 leading-relaxed">
              Have questions about securing your digital legacy? Our team is here to help you navigate the future of inheritance.
            </p>
          </motion.div>
        </div>
      </section>

      <section className="max-w-7xl mx-auto px-6 pb-32">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
          
          {/* Contact Info & Map */}
          <div className="lg:col-span-5 space-y-8">
            <motion.div 
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              className="grid grid-cols-1 gap-6"
            >
              {/* Info Cards */}
              <div className="p-6 rounded-2xl bg-slate-900/50 border border-white/5 backdrop-blur-sm group hover:border-indigo-500/50 transition-colors">
                <div className="flex items-start gap-4">
                  <div className="w-12 h-12 rounded-xl bg-indigo-500/10 flex items-center justify-center text-indigo-400 group-hover:scale-110 transition-transform">
                    <MapPin size={24} />
                  </div>
                  <div>
                    <h3 className="text-lg font-semibold mb-2">Our Office</h3>
                    <p className="text-slate-400 leading-relaxed">
                      {config?.office_address || '123 Legacy Way, Digital District, CA 94105'}
                    </p>
                  </div>
                </div>
              </div>

              <div className="p-6 rounded-2xl bg-slate-900/50 border border-white/5 backdrop-blur-sm group hover:border-indigo-500/50 transition-colors">
                <div className="flex items-start gap-4">
                  <div className="w-12 h-12 rounded-xl bg-blue-500/10 flex items-center justify-center text-blue-400 group-hover:scale-110 transition-transform">
                    <Mail size={24} />
                  </div>
                  <div className="flex-1">
                    <h3 className="text-lg font-semibold mb-2">Email Us</h3>
                    <div className="space-y-2">
                      {config?.emails.map((e, i) => (
                        <div key={i} className="flex justify-between items-center text-slate-400">
                          <span>{e.label}</span>
                          <a href={`mailto:${e.email}`} className="text-indigo-400 hover:underline">{e.email}</a>
                        </div>
                      )) || <p className="text-slate-400">support@transferlegacy.com</p>}
                    </div>
                  </div>
                </div>
              </div>

              <div className="p-6 rounded-2xl bg-slate-900/50 border border-white/5 backdrop-blur-sm group hover:border-indigo-500/50 transition-colors">
                <div className="flex items-start gap-4">
                  <div className="w-12 h-12 rounded-xl bg-emerald-500/10 flex items-center justify-center text-emerald-400 group-hover:scale-110 transition-transform">
                    <Clock size={24} />
                  </div>
                  <div className="flex-1">
                    <h3 className="text-lg font-semibold mb-2">Working Hours</h3>
                    <div className="space-y-2">
                      {config?.working_hours.map((w, i) => (
                        <div key={i} className="flex justify-between items-center text-slate-400">
                          <span>{w.days}</span>
                          <span>{w.hours}</span>
