  const { setAuth, isAuthenticated } = useOpsStore();

  // Redirect if already authenticated
  useEffect(() => {
    if (isAuthenticated) {
      navigate('/ops/dashboard', { replace: true });
    }
  }, [isAuthenticated, navigate]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      const response = await opsApi.post<{ token: string; admin: any }>('/ops/login', {
        email,
        password,
      });
      
      setAuth(response.token, response.admin);
      toast.success('Welcome back, Admin');
      navigate('/ops/dashboard');
    } catch (err: any) {
      setError(err.message || 'Invalid credentials');
      toast.error('Authentication failed');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#020409] flex items-center justify-center p-4 relative overflow-hidden">
      {/* Background Ambience */}
      <div className="absolute inset-0 z-0">
        <div className="absolute top-1/4 left-1/4 w-[500px] h-[500px] bg-indigo-500/10 rounded-full blur-[120px] animate-pulse" />
        <div className="absolute bottom-1/4 right-1/4 w-[500px] h-[500px] bg-blue-500/10 rounded-full blur-[120px] animate-pulse delay-1000" />
      </div>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="relative z-10 w-full max-w-[440px]"
      >
        {/* Logo/Brand Area */}
        <div className="text-center mb-8">
          <motion.div
            initial={{ scale: 0.8 }}
            animate={{ scale: 1 }}
            className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-indigo-600/20 border border-indigo-500/30 mb-4 shadow-xl shadow-indigo-500/10"
          >
            <Shield className="w-8 h-8 text-indigo-400" />
          </motion.div>
          <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">Ops Portal</h1>
          <p className="text-slate-400">Administrative access to Transfer Legacy</p>
        </div>

        <div className="bg-slate-900/40 backdrop-blur-2xl border border-slate-800 rounded-3xl p-8 shadow-2xl">
          <form onSubmit={handleLogin} className="space-y-5">
            <Input
              label="Admin Email"
              type="email"
              placeholder="admin@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="bg-slate-950/50 border-slate-800"
            />

            <Input
              label="Password"
              type="password"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="bg-slate-950/50 border-slate-800"
            />

            <AnimatePresence>
              {error && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  exit={{ opacity: 0, height: 0 }}
                  className="flex items-center gap-2 p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm"
                >
                  <AlertCircle className="w-4 h-4 flex-shrink-0" />
                  {error}
                </motion.div>
              )}
            </AnimatePresence>

            <Button
              type="submit"
              variant="primary"
              className="w-full h-12 rounded-xl text-lg font-semibold group"
              disabled={isLoading}
            >
              {isLoading ? (
                <Loader2 className="w-5 h-5 animate-spin mx-auto" />
              ) : (
                <div className="flex items-center justify-center gap-2">
                  <span>Sign In</span>
                  <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-1" />
                </div>
              )}
            </Button>
          </form>

          <div className="mt-8 pt-6 border-t border-slate-800/50 text-center">
            <p className="text-xs text-slate-500 uppercase tracking-widest font-medium">
              Secure Environment
            </p>
            <p className="text-xs text-slate-600 mt-2 px-6">
              This area is restricted to authorized personnel. All attempts to gain unauthorized access are logged and monitored.
            </p>
          </div>
        </div>
      </motion.div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  UserPlus, 
  Trash2, 
  Shield, 
  Search,  
  ShieldCheck, 
  Calendar, 
  Settings as SettingsIcon,
  Check
} from 'lucide-react';
import { opsApi } from '../../../lib/opsApi';
import { useOpsStore } from '../../../store/useOpsStore';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Badge from '../../../components/ui/Badge';
import Card from '../../../components/ui/Card';
import Modal from '../../../components/ui/Modal';
import toast from 'react-hot-toast';
import { cn } from '../../../utils/cn';

const AVAILABLE_PERMISSIONS = [
  { id: 'read', label: 'Global Read', desc: 'View all basic resources' },
  { id: 'write', label: 'Global Write', desc: 'Create/Modify resources' },
  { id: 'delete', label: 'Global Delete', desc: 'Permanently remove items' },
  { id: 'cms.manage', label: 'Manage CMS', desc: 'Create and edit pages/content' },
  { id: 'admins.manage', label: 'Manage Admins', desc: 'User and role management' },
  { id: 'settings.manage', label: 'System Settings', desc: 'Branding and configuration' },
  { id: 'waitlist.manage', label: 'Waitlist', desc: 'Manage subscribers and status' },
  { id: 'audit.read', label: 'View Logs', desc: 'Access system activity logs' },
];

type Tab = 'admins' | 'roles';

export default function AdminMgmt() {
  const [activeTab, setActiveTab] = useState<Tab>('admins');
  const [admins, setAdmins] = useState<any[]>([]);
  const [roles, setRoles] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<any>(null);
  
  const currentAdmin = useOpsStore(state => state.admin);

  // Form state for new admin
  const [newAdmin, setNewAdmin] = useState({
    email: '',
    password: '',
    role_id: '',
  });

  const [roleForm, setRoleForm] = useState({
    name: '',
    description: '',
    permissions: [] as string[],
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [adminsRes, rolesRes] = await Promise.all([
        opsApi.get<any[]>('/ops/admins'),
        opsApi.get<any[]>('/ops/roles'),
      ]);
      setAdmins(adminsRes);
      setRoles(rolesRes);
      if (rolesRes.length > 0) {
        setNewAdmin(prev => ({ ...prev, role_id: rolesRes[0].id }));
      }
    } catch (err) {
      toast.error('Failed to load data');
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await opsApi.post('/ops/admins', newAdmin);
      toast.success('Administrator created');
      setIsModalOpen(false);
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Failed to create admin');
    }
  };

  const handleDelete = async (id: string) => {
    if (id === currentAdmin?.id) {
      toast.error("You cannot delete your own account");
      return;
    }
    if (!window.confirm('Are you sure you want to remove this administrator?')) return;

    try {
      await opsApi.delete(`/ops/admins/${id}`);
      toast.success('Administrator removed');
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Delete failed');
    }
  };

  const handleRoleAction = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        name: roleForm.name,
        description: roleForm.description,
        permissions: roleForm.permissions,
      };

      if (editingRole) {
        await opsApi.put(`/ops/roles/${editingRole.id}`, payload);
        toast.success('Role updated');
      } else {
        await opsApi.post('/ops/roles', payload);
        toast.success('Role created');
      }

      setIsRoleModalOpen(false);
      setEditingRole(null);
      fetchData();
    } catch (err: any) {
      toast.error(err.message || 'Action failed');
    }
  };

  const openRoleModal = (role?: any) => {
    if (role) {
      setEditingRole(role);
      setRoleForm({
        name: role.name,
        description: role.description || '',
        permissions: role.permissions || [],
      });
    } else {
      setEditingRole(null);
      setRoleForm({ name: '', description: '', permissions: ['read'] });
    }
    setIsRoleModalOpen(true);
  };

  const filteredAdmins = admins.filter(a => 
    (a.email || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
    (a.role_name || '').toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-6"
    >
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-2">
            <ShieldCheck className="text-indigo-500" />
            Control Center
          </h1>
          <p className="text-slate-400 text-sm mt-1">Manage system access and security roles</p>
        </div>
        <div className="flex items-center gap-3">
          {activeTab === 'roles' ? (
             <Button 
                variant="primary" 
                className="rounded-xl flex items-center gap-2"
                onClick={() => openRoleModal()}
              >
                <Shield className="w-4 h-4" />
                Create Role
              </Button>
          ) : (
            <Button 
              variant="primary" 
              className="rounded-xl flex items-center gap-2"
              onClick={() => setIsModalOpen(true)}
            >
              <UserPlus className="w-4 h-4" />
              Add Administrator
            </Button>
          )}
        </div>
      </div>

      <div className="flex gap-2 p-1 bg-slate-900/50 border border-slate-800 rounded-xl w-fit mb-6">
        <button 
          onClick={() => setActiveTab('admins')}
          className={cn(
            "px-4 py-1.5 rounded-lg text-xs font-medium transition-all",
            activeTab === 'admins' ? "bg-slate-800 text-white shadow-lg" : "text-slate-500 hover:text-slate-300"
          )}
        >
          Administrators
        </button>
        <button 
          onClick={() => setActiveTab('roles')}
          className={cn(
            "px-4 py-1.5 rounded-lg text-xs font-medium transition-all",
            activeTab === 'roles' ? "bg-slate-800 text-white shadow-lg" : "text-slate-500 hover:text-slate-300"
          )}
        >
          Roles & Permissions
        </button>
      </div>

      <AnimatePresence mode="wait">
        {activeTab === 'admins' ? (
          <motion.div
            key="admins"
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 10 }}
            className="space-y-6"
          >
            <div className="flex gap-4 mb-6">
              <div className="flex-1 relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
                <input
                  type="text"
                  placeholder="Search by email or role..."
                  className="w-full bg-slate-900/50 border border-slate-800 rounded-xl pl-10 pr-4 py-2.5 text-sm text-slate-200 focus:outline-none focus:border-indigo-500/50 transition-all font-sans"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
            </div>

            <Card className="bg-slate-900/40 border-slate-800 rounded-2xl overflow-hidden p-0">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-800/30 text-slate-400 text-xs uppercase tracking-widest font-bold">
                    <th className="px-6 py-4">Administrator</th>
                    <th className="px-6 py-4">Role</th>
                    <th className="px-6 py-4">Last Login</th>
                    <th className="px-6 py-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800/50">
                  {isLoading ? (
                    <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-500">Loading...</td></tr>
                  ) : filteredAdmins.length === 0 ? (
                    <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-500 font-sans">No administrators found</td></tr>
                  ) : filteredAdmins.map((admin) => (
                    <tr key={admin.id} className="hover:bg-slate-800/20 transition-colors">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-lg bg-slate-800 flex items-center justify-center text-indigo-400 font-bold text-xs">
                            {admin.email.charAt(0).toUpperCase()}
                          </div>
                          <div>
                            <div className="text-sm font-medium text-white">{admin.email}</div>
                            <div className="text-[10px] text-slate-500 font-mono">{admin.id.split('-')[0]}...</div>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <Badge variant={admin.role_name === 'super_admin' ? 'info' : 'default'} className="lowercase">
                          {admin.role_name.replace('_', ' ')}
                        </Badge>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-2 text-xs text-slate-400">
                          <Calendar className="w-3 h-3" />
                          {admin.last_login ? new Date(admin.last_login).toLocaleDateString() : 'Never'}
                        </div>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <button 
                          onClick={() => handleDelete(admin.id)}
                          className="p-2 text-slate-500 hover:text-red-400 transition-colors rounded-lg hover:bg-red-500/10"
                          disabled={admin.id === currentAdmin?.id}
                          title={admin.id === currentAdmin?.id ? "Cannot delete self" : "Delete Admin"}
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </Card>
          </motion.div>
        ) : (
          <motion.div
            key="roles"
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 10 }}
            className="space-y-6"
          >
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {roles.map(role => (
                <Card key={role.id} className="bg-slate-900/40 border-slate-800 p-6 flex flex-col gap-4 group hover:border-indigo-500/20 transition-all">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-xl bg-indigo-500/10 flex items-center justify-center text-indigo-500">
                        <Shield className="w-5 h-5" />
                      </div>
                      <div>
                        <h4 className="font-bold text-white capitalize">{role.name.replace('_', ' ')}</h4>
                        <p className="text-[10px] text-slate-500 font-mono">{role.id.split('-')[0]}...</p>
                      </div>
                    </div>
                    <button 
                      onClick={() => openRoleModal(role)}
                      className="p-2 text-slate-600 hover:text-white transition-colors"
                    >
                      <SettingsIcon className="w-4 h-4" />
                    </button>
                  </div>
                  <p className="text-xs text-slate-400 leading-relaxed min-h-[3rem]">
                    {role.description || 'No description provided for this security role.'}
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {role.permissions.map((p: string) => (
                      <span key={p} className="px-2 py-0.5 rounded-md bg-slate-950 text-[10px] text-slate-500 border border-slate-800">
                        {p}
                      </span>
                    ))}
                  </div>
                </Card>
              ))}
              <button 
                onClick={() => openRoleModal()}
                className="flex flex-col items-center justify-center gap-3 p-8 rounded-2xl bg-slate-950 border border-dashed border-slate-800 text-slate-600 hover:border-indigo-500/30 hover:text-indigo-400 transition-all group"
              >
                <div className="w-12 h-12 rounded-full border border-dashed border-slate-800 flex items-center justify-center group-hover:scale-110 transition-transform">
                  <UserPlus className="w-6 h-6" />
                </div>
                <span className="text-xs font-bold uppercase tracking-widest">New Role</span>
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Create Admin Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)}
        title="Register New Admin"
      >
        <form onSubmit={handleCreate} className="space-y-4">
          <Input
            label="Email Address"
            type="email"
            value={newAdmin.email}
            onChange={(e) => setNewAdmin(prev => ({ ...prev, email: e.target.value }))}
            required
            className="bg-slate-950 border-slate-800"
          />
          <Input
            label="Initial Password"
            type="password"
            value={newAdmin.password}
            onChange={(e) => setNewAdmin(prev => ({ ...prev, password: e.target.value }))}
            required
            className="bg-slate-950 border-slate-800"
          />
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-muted font-sans">Assign Role</label>
            <select
              value={newAdmin.role_id}
              onChange={(e) => setNewAdmin(prev => ({ ...prev, role_id: e.target.value }))}
              className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white focus:outline-none focus:border-indigo-500/50"
            >
              {roles.map(role => (
                <option key={role.id} value={role.id}>{role.name}</option>
              ))}
            </select>
          </div>
          <div className="pt-4 flex justify-end gap-3">
            <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" variant="primary" className="px-8">
              Create Account
            </Button>
          </div>
        </form>
      </Modal>

      {/* Role Config Modal */}
      <Modal 
        isOpen={isRoleModalOpen} 
        onClose={() => setIsRoleModalOpen(false)}
        title={editingRole ? `Update Role: ${editingRole.name}` : "Create Security Role"}
      >
        <form onSubmit={handleRoleAction} className="space-y-4">
          <Input
            label="Role Name"
            value={roleForm.name}
            onChange={(e) => setRoleForm(prev => ({ ...prev, name: e.target.value }))}
            required
            placeholder="e.g. support_staff"
            className="bg-slate-950 border-slate-800"
          />
          <div className="space-y-1.5">
            <label className="text-sm font-medium text-muted">Role Description</label>
            <textarea
              className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white focus:outline-none focus:border-indigo-500/50 text-sm h-24 resize-none"
              value={roleForm.description}
              onChange={(e) => setRoleForm(prev => ({ ...prev, description: e.target.value }))}
              placeholder="What can this role do?"
            />
          </div>
          <div className="space-y-3">
            <label className="text-sm font-medium text-muted">Select Permissions</label>
            <div className="grid grid-cols-1 gap-2 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
              {AVAILABLE_PERMISSIONS.map((perm) => {
                const isSelected = roleForm.permissions.includes(perm.id);
                return (
                  <button
                    key={perm.id}
                    type="button"
                    onClick={() => {
                      const newPerms = isSelected
                        ? roleForm.permissions.filter(p => p !== perm.id)
                        : [...roleForm.permissions, perm.id];
                      setRoleForm({ ...roleForm, permissions: newPerms });
                    }}
                    className={cn(
                      "flex items-start gap-3 p-3 rounded-xl border text-left transition-all",
                      isSelected 
                        ? "bg-indigo-500/10 border-indigo-500/50" 
                        : "bg-slate-950 border-slate-800 hover:border-slate-700"
                    )}
                  >
                    <div className={cn(
                      "mt-0.5 w-4 h-4 rounded border flex items-center justify-center transition-colors",
                      isSelected ? "bg-indigo-500 border-indigo-500" : "bg-transparent border-slate-700"
                    )}>
                      {isSelected && <Check className="w-3 h-3 text-white" />}
                    </div>
                    <div>
                      <p className={cn("text-xs font-bold", isSelected ? "text-indigo-400" : "text-slate-300")}>
                        {perm.label}
                      </p>
                      <p className="text-[10px] text-slate-500 mt-0.5">{perm.desc}</p>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
          
          <div className="pt-4 flex justify-end gap-3">
            <Button type="button" variant="secondary" onClick={() => setIsRoleModalOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" variant="primary" className="px-8">
              {editingRole ? "Save Changes" : "Create Role"}
            </Button>
          </div>
        </form>
      </Modal>
    </motion.div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  ScrollText, 
  Search, 
  Filter, 
  Calendar, 
  User, 
  Activity, 
  Info,
  Clock,
  Shield,
  LogIn,
  RefreshCw,
  ArrowRight
} from 'lucide-react';
import { opsApi } from '../../../lib/opsApi';
import Card from '../../../components/ui/Card';
import Badge from '../../../components/ui/Badge';
import toast from 'react-hot-toast';
import { cn } from '../../../utils/cn';

interface AuditLog {
  id: string;
  admin_id: string | null;
  admin_email: string | null;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  metadata: any | null;
  ip_address: string | null;
  created_at: string;
}

export default function AuditLogs() {
  const [logs, setLogs] = useState<AuditLog[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [filterAction, setFilterAction] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [expandedLog, setExpandedLog] = useState<string | null>(null);

  const ACTIONS = ['login', 'change_password', 'create_admin', 'delete_admin', 'create_role', 'update_role', 'delete_role', 'update_branding', 'update_cms'];

  useEffect(() => {
    fetchLogs();
  }, [filterAction]);

  const fetchLogs = async () => {
    setIsLoading(true);
    try {
      const data = await opsApi.get<AuditLog[]>('/ops/logs', {
        params: {
          ...(filterAction ? { action: filterAction } : {}),
          limit: '100'
        }
      });
      setLogs(data || []);
    } catch (err) {
      toast.error('Failed to load activity logs');
      setLogs([]);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredLogs = logs.filter(log => 
    (log.admin_email?.toLowerCase().includes(searchQuery.toLowerCase()) || false) ||
    (log.action?.toLowerCase().includes(searchQuery.toLowerCase()) || false) ||
    (log.entity_type?.toLowerCase().includes(searchQuery.toLowerCase()) || false)
  );

  const getActionIcon = (action: string) => {
    const act = action || '';
    if (act.includes('login')) return <LogIn className="w-3.5 h-3.5 text-blue-400" />;
    if (act.includes('admin')) return <User className="w-3.5 h-3.5 text-indigo-400" />;
    if (act.includes('role')) return <Shield className="w-3.5 h-3.5 text-amber-400" />;
    if (act.includes('branding') || act.includes('settings') || act.includes('cms')) return <Activity className="w-3.5 h-3.5 text-emerald-400" />;
    return <ScrollText className="w-3.5 h-3.5 text-slate-400" />;
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-2">
            <ScrollText className="text-indigo-500" />
            Audit Logs
          </h1>
          <p className="text-slate-400 text-sm mt-1">Immutable trail of administrative actions and system events</p>
        </div>
        <button 
          onClick={fetchLogs}
          className="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-400 hover:text-white transition-all hover:bg-slate-800"
        >
          <RefreshCw className={cn("w-4 h-4", isLoading && "animate-spin")} />
        </button>
      </div>

      <Card className="bg-slate-900/40 border-slate-800 p-4">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
            <input 
              type="text" 
              placeholder="Search logs by email, action, or entity..."
              className="w-full bg-slate-950 border border-slate-800 rounded-xl pl-10 pr-4 py-2.5 text-sm text-white focus:outline-none focus:border-indigo-500/50"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-slate-500 ml-2" />
            <select
              value={filterAction}
              onChange={(e) => setFilterAction(e.target.value)}
              className="bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-sm text-white focus:outline-none focus:border-indigo-500/50 min-w-[160px]"
            >
              <option value="">All Actions</option>
              {ACTIONS.map(a => (
                <option key={a} value={a}>{a.replace('_', ' ').toUpperCase()}</option>
              ))}
            </select>
          </div>
        </div>
      </Card>

      <div className="space-y-3">
        {isLoading ? (
          <div className="py-20 text-center text-slate-500">Retrieving system logs...</div>
        ) : filteredLogs.length === 0 ? (
          <div className="py-20 text-center text-slate-500 bg-slate-900/20 border border-dashed border-slate-800 rounded-3xl">
            No activity logs found for the current criteria.
          </div>
        ) : filteredLogs.map((log) => (
          <div key={log.id} className="space-y-2">
            <motion.div
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              className={cn(
                "group flex flex-col md:flex-row md:items-center gap-4 p-4 bg-slate-900/40 border transition-all hover:bg-slate-900/60 rounded-2xl",
                expandedLog === log.id ? "border-indigo-500/50 bg-slate-900/80" : "border-slate-800/50"
              )}
            >
              <div className="w-10 h-10 rounded-xl bg-slate-800/50 border border-slate-800 flex items-center justify-center shrink-0">
                {getActionIcon(log.action)}
              </div>
              
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-sm font-bold text-white capitalize">{(log.action || 'Unknown').replace('_', ' ')}</span>
                  <ArrowRight className="w-3 h-3 text-slate-700" />
                  <span className="text-xs font-medium text-slate-400 truncate max-w-[200px]">
                    {log.entity_type ? `${log.entity_type}: ` : ''}
                    <span className="text-indigo-400/80 font-mono text-[10px]">{log.entity_id || 'system'}</span>
                  </span>
                </div>
                <div className="flex items-center gap-3 mt-1">
                  <div className="flex items-center gap-1.5 text-[10px] text-slate-500">
                    <User className="w-3 h-3" />
                    <span className="font-medium text-slate-400">{log.admin_email || 'System Auth'}</span>
                  </div>
                  {log.ip_address && (
                    <div className="flex items-center gap-1.5 text-[10px] text-slate-500 border-l border-slate-800 pl-3">
                      <Activity className="w-3 h-3" />
                      <span>{log.ip_address}</span>
                    </div>
                  )}
                </div>
              </div>

              <div className="flex flex-col items-end gap-2 shrink-0">
                <div className="flex items-center gap-1.5 text-[10px] text-slate-500 font-mono bg-slate-950 px-2 py-1 rounded-md border border-slate-800">
                  <Clock className="w-3 h-3" />
                  {new Date(log.created_at).toLocaleTimeString()}
                  <span className="mx-1 text-slate-800">|</span>
                  {new Date(log.created_at).toLocaleDateString()}
                </div>
                {log.metadata && (
                  <button 
                    onClick={() => setExpandedLog(expandedLog === log.id ? null : log.id)}
                    className="text-[10px] text-indigo-400 hover:text-indigo-300 flex items-center gap-1 group/meta transition-colors"
                  >
                    <Info className="w-3 h-3" />
                    {expandedLog === log.id ? "Hide Details" : "View Details"}
                  </button>
                )}
              </div>
            </motion.div>
            
            <AnimatePresence>
              {expandedLog === log.id && log.metadata && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  exit={{ opacity: 0, height: 0 }}
                  className="overflow-hidden"
                >
                  <div className="mx-4 p-4 bg-slate-950 border-x border-b border-indigo-500/20 rounded-b-2xl">
                    <pre className="text-[10px] font-mono text-slate-400 overflow-x-auto custom-scrollbar p-2 bg-slate-900/50 rounded-lg">
                      {JSON.stringify(log.metadata, null, 2)}
                    </pre>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        ))}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Palette, Save, RefreshCw, Eye, Image as ImageIcon } from 'lucide-react';
import { opsApi } from '../../../lib/opsApi';
import Card from '../../../components/ui/Card';
import Button from '../../../components/ui/Button';
import toast from 'react-hot-toast';

export default function BrandingStudio() {
  const [config, setConfig] = useState<any>({
    brand_name: '',
    logo_url: '',
    support_email: '',
    theme_config: {},
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    fetchBranding();
  }, []);

  const fetchBranding = async () => {
    try {
      const data = await opsApi.get('/ops/branding');
      setConfig(data);
    } catch (err) {
      toast.error('Failed to load branding');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await opsApi.put('/ops/branding', config);
      toast.success('Theme assets updated');
    } catch (err) {
      toast.error('Failed to save changes');
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return <div className="flex items-center justify-center p-20 text-slate-500">Loading Configuration...</div>;
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="max-w-4xl space-y-8"
    >
      <div>
        <h1 className="text-2xl font-bold text-white flex items-center gap-2">
          <Palette className="text-indigo-500" />
          Visual Branding
        </h1>
        <p className="text-slate-400 text-sm mt-1">Configure your application's visual themes and aesthetic assets</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <form onSubmit={handleSave} className="md:col-span-2 space-y-6">
          <Card className="bg-slate-900/40 border-slate-800 p-6 space-y-6">
            <h3 className="text-sm font-bold uppercase tracking-widest text-slate-500">Theme Assets</h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="p-4 rounded-2xl bg-slate-950 border border-indigo-500/30 rounded-2xl flex flex-col items-center gap-3">
                <div className="w-12 h-12 rounded-xl bg-indigo-500/10 flex items-center justify-center text-indigo-400">
                  <div className="w-6 h-6 bg-indigo-500 rounded-full" />
                </div>
                <span className="text-xs font-semibold">Primary Color</span>
              </div>
              <div className="p-4 rounded-2xl bg-slate-950/50 border border-slate-800 rounded-2xl flex flex-col items-center gap-3 opacity-50 cursor-not-allowed">
                <div className="w-12 h-12 rounded-xl bg-slate-800 flex items-center justify-center text-slate-400">
                  <RefreshCw className="w-5 h-5" />
                </div>
                <span className="text-xs font-semibold">Secondary Accent</span>
              </div>
            </div>
          </Card>

          <Card className="bg-slate-900/40 border-slate-800 p-6 space-y-6">
            <h3 className="text-sm font-bold uppercase tracking-widest text-slate-500">Global Styles</h3>
            <div className="p-4 rounded-2xl bg-indigo-500/5 border border-indigo-500/10">
              <p className="text-xs text-indigo-400 leading-relaxed italic">
                Aesthetic controls for border radius, blur intensity, and gradient styles will appear here in the next update.
              </p>
            </div>
          </Card>

          <div className="flex justify-end gap-3">
            <Button variant="secondary" type="button" onClick={fetchBranding} className="border-slate-800">
              Discard
            </Button>
            <Button variant="primary" type="submit" className="px-10" disabled={isSaving}>
              {isSaving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
              Save Theme
            </Button>
          </div>
        </form>

        <div className="space-y-6">
          <h3 className="text-sm font-bold uppercase tracking-widest text-slate-500 flex items-center gap-2">
            <Eye className="w-4 h-4" /> 
            Live Preview
          </h3>
          <Card className="bg-slate-950 border-slate-800 p-0 overflow-hidden shadow-2xl">
            <div className="bg-slate-900/50 p-3 border-b border-slate-800 flex items-center gap-2">
              <div className="flex gap-1.5">
                <div className="w-2.5 h-2.5 rounded-full bg-red-500/50" />
                <div className="w-2.5 h-2.5 rounded-full bg-yellow-500/50" />
                <div className="w-2.5 h-2.5 rounded-full bg-green-500/50" />
              </div>
            </div>
            <div className="p-6 text-center space-y-4">
              <div className="w-16 h-16 bg-slate-900 rounded-2xl mx-auto flex items-center justify-center border border-slate-800">
                {config.logo_url ? (
                  <img src={config.logo_url} alt="Logo" className="max-w-[70%] max-h-[70%] object-contain" />
                ) : (
                  <ImageIcon className="text-slate-700" />
                )}
              </div>
              <div>
                <h4 className="font-bold text-white">{config.brand_name || 'Your Brand'}</h4>
                <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-wider mt-1">Theme Preview</p>
              </div>
            </div>
          </Card>
        </div>
      </div>
    </motion.div>
  );
}

import { useState, useEffect } from 'react';
import { Mail, Phone, MapPin, Globe, Save, Plus, Trash2, MessageSquare, Clock } from 'lucide-react';
import { opsApi } from '../../../lib/opsApi';
import toast from 'react-hot-toast';

interface ContactConfig {
  office_address: string;
  map_embed_url: string;
  emails: { label: string; email: string }[];
  phones: { label: string; number: string }[];
  social_links: Record<string, string>;
  working_hours: { days: string; hours: string }[];
}

interface ContactMessage {
  id: string;
  name: string;
  email: string;
  subject: string;
  message: string;
  is_read: boolean;
  created_at: string;
}

export default function ContactSettings() {
  const [config, setConfig] = useState<ContactConfig | null>(null);
  const [messages, setMessages] = useState<ContactMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<'config' | 'messages'>('config');

  useEffect(() => {
    fetchData();
  }, []);

  async function fetchData() {
    try {
      const [configData, messagesData] = await Promise.all([
        opsApi.get<ContactConfig>('/ops/contact'),
        opsApi.get<ContactMessage[]>('/ops/contact/messages')
      ]);
      setConfig(configData);
      setMessages(messagesData);
    } catch (err) {
      toast.error('Failed to load contact settings');
    } finally {
      setLoading(false);
    }
  }

  const handleSave = async () => {
    if (!config) return;
    setSaving(true);
    try {
      await opsApi.put('/ops/contact', config);
      toast.success('Contact settings updated');
    } catch (err) {
      toast.error('Failed to update settings');
    } finally {
      setSaving(false);
    }
  };

  const addEmail = () => setConfig(prev => prev ? ({ ...prev, emails: [...prev.emails, { label: '', email: '' }] }) : null);
  const removeEmail = (index: number) => setConfig(prev => prev ? ({ ...prev, emails: prev.emails.filter((_, i) => i !== index) }) : null);
  
  const addPhone = () => setConfig(prev => prev ? ({ ...prev, phones: [...prev.phones, { label: '', number: '' }] }) : null);
  const removePhone = (index: number) => setConfig(prev => prev ? ({ ...prev, phones: prev.phones.filter((_, i) => i !== index) }) : null);

  const addWorkingHour = () => setConfig(prev => prev ? ({ ...prev, working_hours: [...prev.working_hours, { days: '', hours: '' }] }) : null);
  const removeWorkingHour = (index: number) => setConfig(prev => prev ? ({ ...prev, working_hours: prev.working_hours.filter((_, i) => i !== index) }) : null);

  if (loading) return <div className="p-8 text-slate-400">Loading...</div>;

  return (
    <div className="p-8 max-w-6xl mx-auto">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-2xl font-bold text-white mb-2">Contact Management</h1>
          <p className="text-slate-400">Configure your professional contact presence and manage inquiries.</p>
        </div>
        <div className="flex gap-2 p-1 bg-slate-900 rounded-lg">
          <button 
            onClick={() => setActiveTab('config')}
            className={`px-4 py-2 rounded-md transition-all ${activeTab === 'config' ? 'bg-indigo-500 text-white' : 'text-slate-400 hover:text-white'}`}
          >
            Configuration
          </button>
          <button 
            onClick={() => setActiveTab('messages')}
            className={`px-4 py-2 rounded-md transition-all flex items-center gap-2 ${activeTab === 'messages' ? 'bg-indigo-500 text-white' : 'text-slate-400 hover:text-white'}`}
          >
            Messages
            {messages.filter(m => !m.is_read).length > 0 && (
              <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
            )}
          </button>
        </div>
      </div>

      {activeTab === 'config' ? (
        <div className="space-y-8">
          {/* Office & Map */}
          <section className="bg-slate-900/50 border border-white/5 rounded-2xl p-6">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <MapPin size={20} className="text-indigo-400" />
              Office & Location
            </h2>
            <div className="grid grid-cols-1 gap-6">
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-2">Office Address</label>
                <textarea 
                  value={config?.office_address || ''}
                  onChange={e => setConfig(prev => prev ? ({ ...prev, office_address: e.target.value }) : null)}
                  className="w-full px-4 py-3 bg-slate-800 border border-white/10 rounded-xl focus:border-indigo-500 outline-none transition-all resize-none"
                  placeholder="Enter full address..."
                  rows={2}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-2">Google Maps Embed URL</label>
                <input 
                  type="text"
                  value={config?.map_embed_url || ''}
                  onChange={e => setConfig(prev => prev ? ({ ...prev, map_embed_url: e.target.value }) : null)}
                  className="w-full px-4 py-3 bg-slate-800 border border-white/10 rounded-xl focus:border-indigo-500 outline-none transition-all"
                  placeholder="https://www.google.com/maps/embed?pb=..."
                />
              </div>
            </div>
          </section>

          {/* Emails & Phones */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <section className="bg-slate-900/50 border border-white/5 rounded-2xl p-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-semibold text-white flex items-center gap-2">
                  <Mail size={20} className="text-blue-400" />
                  Email Addresses
                </h2>
                <button onClick={addEmail} className="p-2 hover:bg-white/5 rounded-lg text-indigo-400 transition-colors">
                  <Plus size={20} />
                </button>
              </div>
              <div className="space-y-4">
                {config?.emails.map((email, idx) => (
                  <div key={idx} className="flex gap-2">
                    <input 
                      placeholder="Label (e.g. Sales)"
                      value={email.label}
                      onChange={e => {
                        const newEmails = [...config.emails];
                        newEmails[idx].label = e.target.value;
                        setConfig({ ...config, emails: newEmails });
                      }}
                      className="w-1/3 px-4 py-2 bg-slate-800 border border-white/10 rounded-lg outline-none"
                    />
                    <input 
                      placeholder="Email"
                      value={email.email}
                      onChange={e => {
                        const newEmails = [...config.emails];
                        newEmails[idx].email = e.target.value;
                        setConfig({ ...config, emails: newEmails });
                      }}
                      className="flex-1 px-4 py-2 bg-slate-800 border border-white/10 rounded-lg outline-none"
                    />
                    <button onClick={() => removeEmail(idx)} className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg">
                      <Trash2 size={18} />
                    </button>
                  </div>
                ))}
              </div>
            </section>

            <section className="bg-slate-900/50 border border-white/5 rounded-2xl p-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-semibold text-white flex items-center gap-2">
                  <Phone size={20} className="text-emerald-400" />
                  Phone Numbers
                </h2>
                <button onClick={addPhone} className="p-2 hover:bg-white/5 rounded-lg text-indigo-400 transition-colors">
                  <Plus size={20} />
                </button>
              </div>
              <div className="space-y-4">
                {config?.phones.map((phone, idx) => (
                  <div key={idx} className="flex gap-2">
                    <input 
                      placeholder="Label"
                      value={phone.label}
                      onChange={e => {
                        const newPhones = [...config.phones];
                        newPhones[idx].label = e.target.value;
                        setConfig({ ...config, phones: newPhones });
                      }}
                      className="w-1/3 px-4 py-2 bg-slate-800 border border-white/10 rounded-lg outline-none"
                    />
                    <input 
                      placeholder="Number"
                      value={phone.number}
                      onChange={e => {
                        const newPhones = [...config.phones];
                        newPhones[idx].number = e.target.value;
                        setConfig({ ...config, phones: newPhones });
                      }}
                      className="flex-1 px-4 py-2 bg-slate-800 border border-white/10 rounded-lg outline-none"
                    />
                    <button onClick={() => removePhone(idx)} className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg">
                      <Trash2 size={18} />
                    </button>
                  </div>
                ))}
              </div>
            </section>
          </div>

          {/* Social Links & Hours */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <section className="bg-slate-900/50 border border-white/5 rounded-2xl p-6">
              <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                <Globe size={20} className="text-purple-400" />
                Social Media
              </h2>
              <div className="space-y-4">
                {['LinkedIn', 'Twitter', 'Facebook', 'Instagram'].map(platform => (
                  <div key={platform} className="flex items-center gap-4">
                    <span className="w-24 text-sm text-slate-400">{platform}</span>
                    <input 
                      type="text"
                      placeholder="URL..."
                      value={config?.social_links[platform] || ''}
                      onChange={e => {
                        const newLinks = { ...config?.social_links, [platform]: e.target.value };
                        setConfig(prev => prev ? ({ ...prev, social_links: newLinks }) : null);
                      }}
                      className="flex-1 px-4 py-2 bg-slate-800 border border-white/10 rounded-lg outline-none focus:border-indigo-500"
                    />
                  </div>
                ))}
              </div>
            </section>

            <section className="bg-slate-900/50 border border-white/5 rounded-2xl p-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-semibold text-white flex items-center gap-2">
                  <Clock size={20} className="text-orange-400" />
                  Working Hours
                </h2>
                <button onClick={addWorkingHour} className="p-2 hover:bg-white/5 rounded-lg text-indigo-400 transition-colors">
                  <Plus size={20} />
                </button>
              </div>
              <div className="space-y-4">
                {config?.working_hours.map((w, idx) => (
                  <div key={idx} className="flex gap-2">
                    <input 
                      placeholder="Days"
                      value={w.days}
                      onChange={e => {
                        const newHours = [...config.working_hours];
                        newHours[idx].days = e.target.value;
                        setConfig({ ...config, working_hours: newHours });
                      }}
                      className="w-1/2 px-4 py-2 bg-slate-800 border border-white/10 rounded-lg outline-none"
                    />
                    <input 
                      placeholder="Hours"
                      value={w.hours}
                      onChange={e => {
                        const newHours = [...config.working_hours];
                        newHours[idx].hours = e.target.value;
                        setConfig({ ...config, working_hours: newHours });
                      }}
                      className="flex-1 px-4 py-2 bg-slate-800 border border-white/10 rounded-lg outline-none"
                    />
                    <button onClick={() => removeWorkingHour(idx)} className="p-2 text-red-400 hover:bg-red-400/10 rounded-lg">
                      <Trash2 size={18} />
                    </button>
                  </div>
                ))}
              </div>
            </section>
          </div>

          {/* Save Button */}
          <div className="flex justify-end pt-4">
            <button 
              onClick={handleSave}
              disabled={saving}
              className="flex items-center gap-2 bg-indigo-500 hover:bg-indigo-600 disabled:opacity-50 px-8 py-3 rounded-xl font-bold text-white transition-all transform active:scale-95 shadow-lg shadow-indigo-500/20"
            >
              {saving ? 'Saving...' : (
                <>
                  <Save size={20} />
                  Save Configuration
                </>
              )}
            </button>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          {messages.length === 0 ? (
            <div className="text-center py-20 bg-slate-900/30 rounded-2xl border border-dashed border-white/10">
              <MessageSquare size={48} className="mx-auto text-slate-600 mb-4" />
              <p className="text-slate-400 font-medium">No messages yet.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 gap-4">
              {messages.map(msg => (
                <div key={msg.id} className="p-6 bg-slate-900/50 border border-white/5 rounded-2xl relative group transition-all hover:border-indigo-500/30">
                  {!msg.is_read && (
                    <div className="absolute top-6 right-6 w-2 h-2 bg-indigo-500 rounded-full shadow-[0_0_10px_rgba(99,102,241,0.5)]" />
                  )}
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h3 className="text-lg font-bold text-white mb-1">{msg.subject || 'No Subject'}</h3>
                      <div className="flex items-center gap-3 text-sm">
                        <span className="text-slate-200">{msg.name}</span>
                        <span className="text-slate-600">•</span>
                        <a href={`mailto:${msg.email}`} className="text-indigo-400 hover:underline">{msg.email}</a>
                        <span className="text-slate-600">•</span>
                        <span className="text-slate-500">{new Date(msg.created_at).toLocaleString()}</span>
                      </div>
                    </div>
                    <button className="p-2 text-slate-500 hover:text-white transition-colors">
                      <Trash2 size={20} />
                    </button>
                  </div>
                  <p className="text-slate-400 leading-relaxed bg-slate-800/50 p-4 rounded-xl">
                    {msg.message}
                  </p>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { 
  Users, 
  Activity, 
  Shield, 
  Mail, 
  TrendingUp, 
  Clock,
  ArrowUpRight,
  ShieldCheck,
  Globe
} from 'lucide-react';
import { opsApi } from '../../../lib/opsApi';
import StatCard from '../../../components/ui/StatCard';
import Card from '../../../components/ui/Card';
import Badge from '../../../components/ui/Badge';
import Button from '../../../components/ui/Button';
import { Link } from 'react-router-dom';

export default function OpsDashboard() {
  const [stats, setStats] = useState({
    waitlistCount: 0,
    adminCount: 0,
    systemStatus: 'Operational',
  });
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      const [waitlist, admins] = await Promise.all([
        opsApi.get<any[]>('/ops/waitlist'),
        opsApi.get<any[]>('/ops/admins'),
      ]);
      setStats({
        waitlistCount: waitlist.length,
        adminCount: admins.length,
        systemStatus: 'Operational',
      });
    } catch (err) {
      console.error('Failed to fetch stats');
    } finally {
      setIsLoading(false);
    }
  };

  const container = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const item = {
    hidden: { opacity: 0, y: 20 },
    show: { opacity: 1, y: 0 }
  };

  return (
    <motion.div
      variants={container}
      initial="hidden"
      animate="show"
      className="space-y-10"
    >
      {/* Welcome Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-bold text-white tracking-tight">System Overview</h1>
          <p className="text-slate-400 mt-2 flex items-center gap-2">
            <span className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse" />
            Live infrastructure monitoring for {new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
          </p>
        </div>
        <div className="flex gap-3">
          <Link to="/ops/waitlist">
            <Button variant="secondary" className="rounded-xl border-slate-800 bg-slate-900/50">
              View Analytics
            </Button>
          </Link>
          <Link to="/ops/branding">
            <Button variant="primary" className="rounded-xl glow-blue">
              Studio Config
            </Button>
          </Link>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <motion.div variants={item}>
          <StatCard
            title="Total Waitlist"
            value={stats.waitlistCount}
            icon={<Users className="w-5 h-5" />}
            trend={{ value: 12, label: 'from last week', positive: true }}
            className="bg-slate-900/40 border-slate-800 hover:border-indigo-500/30 transition-all cursor-default"
          />
        </motion.div>
        <motion.div variants={item}>
          <StatCard
            title="System Admins"
            value={stats.adminCount}
            icon={<Shield className="w-5 h-5" />}
            className="bg-slate-900/40 border-slate-800 hover:border-indigo-500/30 transition-all cursor-default"
          />
        </motion.div>
        <motion.div variants={item}>
          <StatCard
            title="API Latency"
            value={24}
            suffix="ms"
            icon={<Activity className="w-5 h-5" />}
            trend={{ value: 4, label: 'optimized', positive: true }}
            className="bg-slate-900/40 border-slate-800 hover:border-indigo-500/30 transition-all cursor-default"
          />
        </motion.div>
        <motion.div variants={item}>
          <StatCard
            title="Service Status"
            value={stats.systemStatus}
            icon={<ShieldCheck className="w-5 h-5" />}
            className="bg-slate-900/40 border-slate-800 hover:border-indigo-500/30 transition-all cursor-default"
          />
        </motion.div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Recent Activity / System Log */}
        <motion.div variants={item} className="lg:col-span-2 space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-white flex items-center gap-2">
              <Clock className="w-5 h-5 text-indigo-400" />
              Recent Operations
            </h3>
            <button className="text-xs text-indigo-400 font-bold hover:underline">View Audit Log</button>
          </div>
          <Card className="bg-slate-950 border-slate-800 p-0 overflow-hidden divide-y divide-slate-800/50">
            {[1, 2, 3].map((i) => (
              <div key={i} className="p-4 flex items-center justify-between group hover:bg-slate-900/40 transition-colors">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-center text-slate-500 group-hover:text-indigo-400 group-hover:border-indigo-500/30 transition-all">
                    <TrendingUp className="w-5 h-5" />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-white">Branding Configuration Update</p>
                    <p className="text-xs text-slate-500">System updated by admin@transferlegacy.com</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-xs text-slate-400">2h ago</p>
                  <Badge variant="success" className="text-[9px] mt-1">success</Badge>
                </div>
              </div>
            ))}
          </Card>
        </motion.div>

        {/* Quick Insights */}
        <motion.div variants={item} className="space-y-4">
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <ArrowUpRight className="w-5 h-5 text-indigo-400" />
            Quick Insights
          </h3>
          <Card className="bg-indigo-600/10 border-indigo-500/20 p-6 relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
              <Globe className="w-20 h-20 text-indigo-500" />
            </div>
            <p className="text-sm text-indigo-300 font-medium">Growth Target</p>
            <h4 className="text-2xl font-bold text-white mt-2">Targeting 500+</h4>
            <p className="text-xs text-indigo-400/80 mt-1 leading-relaxed">
              Based on recent waitlist velocity, we are on track to exceed our pre-launch goals.
            </p>
            <div className="mt-6 flex items-center justify-between">
              <div className="flex -space-x-2">
                {[1, 2, 3, 4].map(i => (
                  <div key={i} className="w-6 h-6 rounded-full bg-slate-800 border-2 border-[#020409]" />
                ))}
              </div>
              <span className="text-xs font-bold text-indigo-400">+18% this month</span>
            </div>
          </Card>
          
          <Card className="bg-slate-900/40 border-slate-800 p-6">
            <div className="flex items-center gap-3 mb-4">
              <div className="p-2 rounded-lg bg-slate-800">
                <Mail className="w-4 h-4 text-slate-400" />
              </div>
              <p className="text-sm font-bold text-white">System Notifications</p>
            </div>
            <p className="text-xs text-slate-500 leading-relaxed italic">
              "No critical system alerts. Infrastructure is stable across all regions."
            </p>
          </Card>
        </motion.div>
      </div>
    </motion.div>
  );
}

