import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  FileText, 
  Search, 
  Save, 
  RefreshCw, 
  ExternalLink,
  Layout,
  Type,
  HelpCircle,
  AlertCircle,
  Users,
  Plus,
  Trash2,
  Image as ImageIcon,
  User
} from 'lucide-react';
import { opsApi } from '../../../lib/opsApi';
import Card from '../../../components/ui/Card';
import Button from '../../../components/ui/Button';
import toast from 'react-hot-toast';
import { cn } from '../../../utils/cn';

const DEFAULT_SLUGS = ['hero', 'faqs', 'features', 'team'];

const DEFAULT_STRUCTURES: Record<string, any> = {
  hero: { title: 'Welcome to Transfer Legacy', subtitle: 'Secure your digital legacy today.' },
  faqs: { items: [{ q: 'Example Question?', a: 'Example Answer.' }] },
  features: { items: [{ title: 'Secure Vault', description: 'End-to-end encrypted storage.' }] },
  team: { items: [{ name: 'John Doe', role: 'Founder', bio: 'Passionate about digital legacy.', imageUrl: '' }] }
};

export default function LeanCMS() {
  const [selectedSlug, setSelectedSlug] = useState<string>(DEFAULT_SLUGS[0]);
  const [formData, setFormData] = useState<any>({});
  const [currentVersion, setCurrentVersion] = useState<number>(1);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    fetchContent();
  }, [selectedSlug]);

  const fetchContent = async () => {
    setIsLoading(true);
    try {
      const data = await opsApi.get<any>(`/app/content/${selectedSlug}`);
      setFormData(data.body || DEFAULT_STRUCTURES[selectedSlug] || {});
      setCurrentVersion(data.version || 1);
    } catch (err) {
      // If content doesn't exist, initialize with default structure
      setFormData(DEFAULT_STRUCTURES[selectedSlug] || {});
      setCurrentVersion(1);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    setIsSaving(true);
    try {
      // Use the new /ops/content endpoint which is unencrypted
      await opsApi.put('/ops/content', {
        slug: selectedSlug,
        body: formData,
        version: currentVersion
      });
      toast.success(`${selectedSlug.toUpperCase()} changes published!`);
      // After save, the backend might increment version or keep it. 
      // The ON CONFLICT DO UPDATE SET version = EXCLUDED.version means it stays what we sent.
    } catch (err: any) {
      toast.error(err.message || 'Failed to publish changes');
    } finally {
      setIsSaving(false);
    }
  };

  const updateField = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const filteredSlugs = DEFAULT_SLUGS.filter(s => s.includes(searchQuery.toLowerCase()));

  const renderEditor = () => {
    switch (selectedSlug) {
      case 'hero':
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-widest pl-1">Main Title</label>
              <input 
                type="text"
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500/50 transition-all font-medium"
                value={formData.title || ''}
                onChange={(e) => updateField('title', e.target.value)}
                placeholder="Enter hero title..."
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-widest pl-1">Subtitle / Slogan</label>
              <textarea 
                className="w-full h-32 bg-slate-950 border border-slate-800 rounded-2xl px-4 py-3 text-white focus:outline-none focus:border-indigo-500/50 transition-all resize-none leading-relaxed"
                value={formData.subtitle || ''}
                onChange={(e) => updateField('subtitle', e.target.value)}
                placeholder="Enter hero subtitle..."
              />
            </div>
          </div>
        );

      case 'faqs':
        const faqItems = formData.items || [];
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-widest pl-1">FAQ Items</label>
              <Button 
                variant="secondary" 
                size="sm" 
                className="bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 hover:bg-indigo-500/20 py-1"
                onClick={() => updateField('items', [...faqItems, { q: 'New Question', a: 'New Answer' }])}
              >
                <Plus className="w-4 h-4 mr-1" /> Add FAQ
              </Button>
            </div>
            <div className="space-y-4">
              {faqItems.map((item: any, idx: number) => (
                <div key={idx} className="bg-slate-950 border border-slate-800 p-4 rounded-2xl relative group">
                  <div className="space-y-3 pr-10">
                    <input 
                      type="text"
                      className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white font-semibold"
                      value={item.q || ''}
                      onChange={(e) => {
                        const newItems = [...faqItems];
                        newItems[idx].q = e.target.value;
                        updateField('items', newItems);
                      }}
                      placeholder="Question"
                    />
                    <textarea 
                      className="w-full h-20 bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-slate-400"
                      value={item.a || ''}
                      onChange={(e) => {
                        const newItems = [...faqItems];
                        newItems[idx].a = e.target.value;
                        updateField('items', newItems);
                      }}
                      placeholder="Answer"
                    />
                  </div>
                  <button 
                    onClick={() => updateField('items', faqItems.filter((_: any, i: number) => i !== idx))}
                    className="absolute top-4 right-4 p-2 text-slate-700 hover:text-red-500 transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        );

      case 'features':
        const featItems = formData.items || [];
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-widest pl-1">Site Features</label>
              <Button 
                variant="secondary" 
                size="sm" 
                className="bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 hover:bg-indigo-500/20 py-1"
                onClick={() => updateField('items', [...featItems, { title: 'New Feature', description: 'Description' }])}
              >
                <Plus className="w-4 h-4 mr-1" /> Add Feature
              </Button>
            </div>
            <div className="space-y-4">
              {featItems.map((item: any, idx: number) => (
                <div key={idx} className="bg-slate-950 border border-slate-800 p-5 rounded-2xl flex gap-4">
                  <div className="flex-1 space-y-3">
                    <input 
                      type="text"
                      className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white font-bold"
                      value={item.title || ''}
                      onChange={(e) => {
                        const newItems = [...featItems];
                        newItems[idx].title = e.target.value;
                        updateField('items', newItems);
                      }}
                      placeholder="Feature Title"
                    />
                    <textarea 
                      className="w-full h-16 bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-xs text-slate-400 mt-2"
                      value={item.description || ''}
                      onChange={(e) => {
                        const newItems = [...featItems];
                        newItems[idx].description = e.target.value;
                        updateField('items', newItems);
                      }}
                      placeholder="Feature Description"
                    />
                  </div>
                  <button 
                    onClick={() => updateField('items', featItems.filter((_: any, i: number) => i !== idx))}
                    className="p-2 text-slate-700 hover:text-red-500"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        );

      case 'team':
        const teamItems = formData.items || [];
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-widest pl-1">Team Members</label>
              <Button 
                variant="secondary" 
                size="sm" 
                className="bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 hover:bg-indigo-500/20 py-1"
                onClick={() => updateField('items', [...teamItems, { name: 'Full Name', role: 'Job Title', bio: 'Short bio...', imageUrl: '' }])}
              >
                <Plus className="w-4 h-4 mr-1" /> Add Member
              </Button>
            </div>
            <div className="grid grid-cols-1 gap-6">
              {teamItems.map((member: any, idx: number) => (
                <Card key={idx} className="bg-slate-950 border-slate-800 p-6 flex flex-col md:flex-row gap-6 items-start">
                  <div className="w-24 h-24 rounded-2xl bg-slate-900 border border-slate-800 flex items-center justify-center shrink-0 overflow-hidden relative group">
                    {member.imageUrl ? (
                      <img src={member.imageUrl} alt={member.name} className="w-full h-full object-cover" />
                    ) : (
                      <User className="w-10 h-10 text-slate-700" />
                    )}
                    <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-2">
                       <input 
                         type="text" 
                         className="w-full bg-slate-800/80 border border-slate-700 rounded text-[10px] text-white px-1 outline-none"
                         placeholder="URL..."
                         value={member.imageUrl || ''}
                         onChange={(e) => {
                            const newItems = [...teamItems];
                            newItems[idx].imageUrl = e.target.value;
                            updateField('items', newItems);
                         }}
                       />
                    </div>
                  </div>
                  <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-600 uppercase ml-1">Name</label>
                      <input 
                        type="text"
                        className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white font-bold"
                        value={member.name || ''}
                        onChange={(e) => {
                          const newItems = [...teamItems];
                          newItems[idx].name = e.target.value;
                          updateField('items', newItems);
                        }}
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-bold text-slate-600 uppercase ml-1">Role</label>
                      <input 
                        type="text"
                        className="w-full bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-sm text-indigo-400"
                        value={member.role || ''}
                        onChange={(e) => {
                          const newItems = [...teamItems];
                          newItems[idx].role = e.target.value;
                          updateField('items', newItems);
                        }}
                      />
                    </div>
                    <div className="md:col-span-2 space-y-1">
                      <label className="text-[10px] font-bold text-slate-600 uppercase ml-1">Biography</label>
                      <textarea 
                        className="w-full h-20 bg-slate-900 border border-slate-800 rounded-lg px-3 py-2 text-xs text-slate-400 resize-none"
                        value={member.bio || ''}
                        onChange={(e) => {
                          const newItems = [...teamItems];
                          newItems[idx].bio = e.target.value;
                          updateField('items', newItems);
                        }}
                      />
                    </div>
                  </div>
                  <button 
                    onClick={() => updateField('items', teamItems.filter((_: any, i: number) => i !== idx))}
                    className="p-2 text-slate-700 hover:text-red-500"
                  >
                    <Trash2 className="w-5 h-5" />
                  </button>
                </Card>
              ))}
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-2">
            <FileText className="text-indigo-500 shadow-glow shadow-indigo-500/20" />
            Lean CMS
          </h1>
          <p className="text-slate-400 text-sm mt-1">Manage landing page content via visual forms</p>
        </div>
        <div className="flex items-center gap-3">
          <Button 
            className="bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 hover:bg-indigo-500/20" 
            onClick={fetchContent}
            disabled={isLoading}
          >
            <RefreshCw className={cn("w-4 h-4 mr-2", isLoading && "animate-spin")} />
            Reload
          </Button>
          <Button 
            variant="primary" 
            className="px-8 shadow-xl shadow-indigo-500/10" 
            onClick={handleSave} 
            disabled={isSaving || isLoading}
          >
            {isSaving ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
            Publish Changes
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Navigation */}
        <Card className="bg-slate-900/40 border-slate-800 p-4 h-fit space-y-4">
           <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-600" />
              <input 
                type="text" 
                placeholder="Search..."
                className="w-full bg-slate-950 border border-slate-800 rounded-xl pl-9 pr-4 py-2 text-xs text-white focus:outline-none focus:border-indigo-500/50 transition-all font-medium"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
           </div>
           <div className="space-y-1">
              {filteredSlugs.map(slug => (
                <button
                  key={slug}
                  onClick={() => setSelectedSlug(slug)}
                  className={cn(
                    "w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center gap-3",
                    selectedSlug === slug 
                      ? "bg-indigo-500/10 text-indigo-400 border-l-4 border-l-indigo-500" 
                      : "text-slate-500 hover:bg-slate-800/50 hover:text-slate-300"
                  )}
                >
                  {slug === 'hero' && <Layout className="w-4 h-4" />}
                  {slug === 'faqs' && <HelpCircle className="w-4 h-4" />}
                  {slug === 'features' && <Type className="w-4 h-4" />}
                  {slug === 'team' && <Users className="w-4 h-4" />}
                  <span className="capitalize">{slug} Section</span>
                </button>
              ))}
           </div>
        </Card>

        {/* Form Editor */}
        <div className="lg:col-span-3">
          <Card className="bg-slate-900/20 border-slate-800 p-8 min-h-[600px] border-2 backdrop-blur-sm relative overflow-hidden">
             {/* Decorative Background */}
             <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-indigo-500/5 rounded-full blur-3xl pointer-events-none" />
             
             {isLoading ? (
               <div className="flex flex-col items-center justify-center py-40 space-y-4">
                  <div className="w-10 h-10 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin" />
                  <p className="text-slate-500 text-xs font-bold uppercase tracking-widest animate-pulse">Syncing Schema...</p>
               </div>
             ) : (
               <>
                 <div className="mb-8 border-b border-slate-800 pb-6 flex items-center justify-between">
                    <div>
                      <h2 className="text-xl font-bold text-white capitalize">{selectedSlug} Content</h2>
                      <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mt-1">Version {currentVersion} • Active Component</p>
                    </div>
                 </div>
                 {renderEditor()}
               </>
             )}
          </Card>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Settings, Globe, Mail, Save, RefreshCw, Shield, Bell, Phone, MapPin } from 'lucide-react';
import { opsApi } from '../../../lib/opsApi';
import Card from '../../../components/ui/Card';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import toast from 'react-hot-toast';

export default function GlobalSettings() {
  const [settings, setSettings] = useState<any>({
    brand_name: '',
    support_email: '',
    support_phone: '',
    support_address: '',
    registration_enabled: true,
    maintenance_mode: false,
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    setIsLoading(true);
    try {
      const data = await opsApi.get('/ops/branding'); 
      setSettings(data);
    } catch (err) {
      toast.error('Failed to load settings');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await opsApi.put('/ops/branding', settings);
      toast.success('Settings updated');
    } catch (err) {
      toast.error('Failed to save settings');
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return <div className="flex items-center justify-center p-20 text-slate-500 text-sm tracking-widest uppercase animate-pulse">Initializing System Config...</div>;
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className="max-w-4xl space-y-8"
    >
      <div>
        <h1 className="text-2xl font-bold text-white flex items-center gap-2">
          <Settings className="text-indigo-500" />
          Global Settings
        </h1>
        <p className="text-slate-400 text-sm mt-1">Manage critical system-wide configurations and contact info</p>
      </div>

      <form onSubmit={handleSave} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <Card className="bg-slate-900/40 border-slate-800 p-6 space-y-6">
            <h3 className="text-sm font-bold uppercase tracking-widest text-slate-500 flex items-center gap-2">
              <Globe className="w-4 h-4" /> Regional & Identity
            </h3>
            
            <Input
              label="Public Brand Name"
              value={settings.brand_name || ''}
              onChange={(e) => setSettings({ ...settings, brand_name: e.target.value })}
              className="bg-slate-950 border-slate-800"
            />

            <div className="space-y-4 pt-2">
              <div className="relative">
                <Mail className="absolute left-3 top-[38px] w-4 h-4 text-slate-500" />
                <Input
                  label="Support Email"
                  type="email"
                  value={settings.support_email || ''}
                  onChange={(e) => setSettings({ ...settings, support_email: e.target.value })}
                  className="bg-slate-950 border-slate-800 pl-10"
                />
              </div>

              <div className="relative">
                <Phone className="absolute left-3 top-[38px] w-4 h-4 text-slate-500" />
                <Input
                  label="Support Phone"
                  type="text"
                  value={settings.support_phone || ''}
                  onChange={(e) => setSettings({ ...settings, support_phone: e.target.value })}
                  className="bg-slate-950 border-slate-800 pl-10"
                  placeholder="+1 (234) 567-890"
                />
              </div>

              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase flex items-center gap-2 ml-1 mb-1">
                   <MapPin className="w-3 h-3" /> Support Address
                </label>
                <textarea
                  className="w-full h-24 bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white focus:outline-none focus:border-indigo-500/50 transition-all resize-none"
                  value={settings.support_address || ''}
                  onChange={(e) => setSettings({ ...settings, support_address: e.target.value })}
                  placeholder="Enter office address..."
                />
              </div>
            </div>
          </Card>

          <Card className="bg-slate-900/40 border-slate-800 p-6 space-y-6">
            <h3 className="text-sm font-bold uppercase tracking-widest text-slate-500 flex items-center gap-2">
              <Shield className="w-4 h-4" /> System Control
            </h3>
            
            <div className="space-y-4">
              <div className="flex items-center justify-between p-4 rounded-xl bg-slate-950/50 border border-slate-800">
                <div>
                  <p className="text-sm font-medium text-white">Public Registration</p>
                  <p className="text-[10px] text-slate-500">Allow new users to create accounts</p>
                </div>
                <input 
                  type="checkbox" 
                  checked={settings.registration_enabled ?? true}
                  onChange={(e) => setSettings({ ...settings, registration_enabled: e.target.checked })}
                  className="w-5 h-5 rounded border-slate-800 bg-slate-900 text-indigo-500 focus:ring-indigo-500/20"
                />
              </div>

              <div className="flex items-center justify-between p-4 rounded-xl bg-slate-950/50 border border-slate-800">
                <div>
                  <p className="text-sm font-medium text-white">Maintenance Mode</p>
                  <p className="text-[10px] text-slate-500">Restrict access to all public services</p>
                </div>
                <input 
                  type="checkbox" 
                  checked={settings.maintenance_mode ?? false}
                  onChange={(e) => setSettings({ ...settings, maintenance_mode: e.target.checked })}
                  className="w-5 h-5 rounded border-slate-800 bg-slate-900 text-red-500 focus:ring-red-500/20"
                />
              </div>
            </div>
          </Card>
        </div>

        <Card className="bg-indigo-500/5 border-indigo-500/20 p-6">
          <div className="flex items-start gap-4">
            <div className="w-10 h-10 rounded-full bg-indigo-500/20 flex items-center justify-center text-indigo-400">
              <Bell className="w-5 h-5" />
            </div>
            <div>
              <h4 className="text-sm font-bold text-white">Direct Deployment</h4>
              <p className="text-xs text-slate-400 mt-1 leading-relaxed">
                Changes made here are applied immediately to all system contacts and service flags. Ensure all details are verified before saving.
              </p>
            </div>
          </div>
        </Card>

        <div className="flex justify-end gap-3 pt-4">
          <Button variant="secondary" type="button" onClick={fetchSettings} className="border-slate-800">
            Discard
          </Button>
          <Button variant="primary" type="submit" className="px-10" disabled={isSaving}>
            {isSaving ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : <Save className="w-4 h-4 mr-2" />}
            Save All Settings
          </Button>
        </div>
      </form>
    </motion.div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Palette, 
  Globe, 
  Upload, 
  Save, 
  RefreshCw, 
  Eye, 
  Image as ImageIcon,
  Settings,
  ShieldAlert,
  Moon,
  Monitor,
  Users
} from 'lucide-react';
import { opsApi } from '../../../lib/opsApi';
import Card from '../../../components/ui/Card';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import toast from 'react-hot-toast';
import { cn } from '../../../utils/cn';

type Tab = 'identity' | 'theme' | 'controls';

export default function SystemSettings() {
  const [activeTab, setActiveTab] = useState<Tab>('identity');
  const [config, setConfig] = useState<any>({
    brand_name: '',
    logo_url: '',
    support_email: '',
    support_phone: '',
    support_address: '',
    waitlist_enabled: true,
    theme_config: {
      primaryColor: '#6366f1',
      darkMode: true,
      maintenanceMode: false
    },
  });
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isUploadingLogo, setIsUploadingLogo] = useState(false);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    try {
      const data = await opsApi.get('/ops/branding');
      setConfig(data);
    } catch (err) {
      toast.error('Failed to load settings');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      await opsApi.put('/ops/branding', config);
      toast.success('Configuration updated successfully');
    } catch (err) {
      toast.error('Failed to save changes');
    } finally {
      setIsSaving(false);
    }
  };

  const handleLogoUpload = async (file: File) => {
    if (!file.type.startsWith('image/')) {
      toast.error('Please choose an image file');
      return;
    }

    setIsUploadingLogo(true);
    try {
      const presign = await opsApi.post<{ upload_url: string; public_url: string }>(
        '/ops/storage/presigned-logo',
        {
          file_name: file.name,
          content_type: file.type,
        },
      );

      // In a real environment, we would PUT to presign.upload_url
      // For this demo, we'll simulate the upload success
      setConfig((prev: any) => ({ ...prev, logo_url: presign.public_url }));
      toast.success('Logo uploaded. Save settings to publish.');
    } catch (err: any) {
      toast.error(err.message || 'Failed to upload logo');
    } finally {
      setIsUploadingLogo(false);
    }
  };

  if (isLoading) {
    return <div className="flex items-center justify-center p-20 text-slate-500">Loading Configuration...</div>;
  }

  const tabs = [
    { id: 'identity', label: 'Site Identity', icon: Globe },
    { id: 'controls', label: 'System Controls', icon: Settings },
    { id: 'theme', label: 'Theme & UI', icon: Palette },
  ];

  return (
    <div className="max-w-5xl space-y-8 pb-12">
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-2xl font-bold text-white flex items-center gap-2">
            <Settings className="text-indigo-500" />
            System Configuration
          </h1>
          <p className="text-slate-400 text-sm mt-1">Manage global brand identity, system behaviors, and visual themes</p>
        </div>
        <Button variant="primary" onClick={handleSave} disabled={isSaving} className="px-8 shadow-lg shadow-indigo-500/20">
          {isSaving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4 mr-2" />}
          Save Changes
        </Button>
      </div>

      <div className="flex gap-2 p-1.5 bg-slate-900/50 border border-slate-800 rounded-2xl w-fit">
        {tabs.map((tab) => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as Tab)}
              className={cn(
                "flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all duration-300 text-sm font-medium",
                isActive 
                  ? "bg-slate-800 text-white shadow-xl border border-slate-700/50" 
                  : "text-slate-400 hover:text-slate-200"
              )}
            >
              <Icon className="w-4 h-4" />
              {tab.label}
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <AnimatePresence mode="wait">
            {activeTab === 'identity' && (
              <motion.div
                key="identity"
                initial={{ opacity: 0, x: -10 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 10 }}
                className="space-y-6"
              >
                <Card className="bg-slate-900/40 border-slate-800 p-6 space-y-6">
                  <h3 className="text-sm font-bold uppercase tracking-widest text-slate-500">Brand Identity</h3>
                  <Input
                    label="Business Name"
                    value={config.brand_name}
                    onChange={(e) => setConfig({ ...config, brand_name: e.target.value })}
                    placeholder="Transfer Legacy"
                    className="bg-slate-950 border-slate-800"
                  />
                  
                  <div className="space-y-1.5">
                    <label className="text-sm font-medium text-slate-400">Brand Logo</label>
                    <input
                      ref={logoInputRef}
                      type="file"
                      accept="image/*"
                      className="hidden"
                      onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) handleLogoUpload(file);
                      }}
                    />
                    <div className="flex gap-3">
                      <input
                        type="text"
                        className="flex-1 bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white focus:outline-none focus:border-indigo-500/50"
                        value={config.logo_url || ''}
                        onChange={(e) => setConfig({ ...config, logo_url: e.target.value })}
                        placeholder="https://..."
                      />
                      <Button
                        variant="secondary"
                        type="button"
                        className="px-3 border-slate-800"
                        disabled={isUploadingLogo}
                        onClick={() => logoInputRef.current?.click()}
                      >
                        {isUploadingLogo ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
                      </Button>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <Input
                      label="Support Email"
                      type="email"
                      value={config.support_email || ''}
                      onChange={(e) => setConfig({ ...config, support_email: e.target.value })}
                      placeholder="support@transferlegacy.com"
                      className="bg-slate-950 border-slate-800"
                    />
                    <Input
                      label="Support Phone"
                      value={config.support_phone || ''}
                      onChange={(e) => setConfig({ ...config, support_phone: e.target.value })}
                      placeholder="+1 (555) 000-0000"
                      className="bg-slate-950 border-slate-800"
                    />
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-sm font-medium text-slate-400">Headquarters Address</label>
                    <textarea
                      className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-white focus:outline-none focus:border-indigo-500/50 resize-none"
                      rows={3}
                      value={config.support_address || ''}
                      onChange={(e) => setConfig({ ...config, support_address: e.target.value })}
                      placeholder="Enter full business address..."
                    />
                  </div>
                </Card>
              </motion.div>
            )}

            {activeTab === 'controls' && (
              <motion.div
                key="controls"
                initial={{ opacity: 0, x: -10 }}
